import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const b=JSON.parse('{"title":"官方教程知识索引","description":"","frontmatter":{},"headers":[],"relativePath":"教程资料/官方教程知识索引.md","filePath":"教程资料/官方教程知识索引.md","lastUpdated":1777893104000}'),h={name:"教程资料/官方教程知识索引.md"};function d(o,l,c,n,u,t){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="官方教程知识索引" tabindex="-1">官方教程知识索引 <a class="header-anchor" href="#官方教程知识索引" aria-label="Permalink to “官方教程知识索引”">​</a></h1><ul><li>分类：教程</li><li>子系统：素材 / 组件 / 广播 / UI / 指令 / 脚本 / 数据结构 / 变量 / 坐标向量 / 控制流</li><li>关键词标签：官方教程, 广播, 自定义组件, 素材, UI, 组件, 指令, 脚本, 变量, 配置表, 坐标, 向量, 判断, 循环, 等待, 渐变</li><li>来源类型：官方教程</li><li>证据等级：官方说明 + 截图直接证据</li><li>完整度状态：持续扩展中</li><li>版本号：未标注</li><li>来源文件：<code>资料/官方教程文档截图/</code></li><li>来源状态：历史 OCR 已入档；当前 <code>资料/官方教程文档截图/</code> 目录未列出可直接 OCR 的原图文件</li><li>来源截图编号：105844, 105850, 105946, 110008, 110035, 110140, 110143, 110222, 110225, 110352, 110404, 110423, 110426, 110535, 112302, 112334, 112406, 112706, 112726, 112739, 112756, 112814, 112843, 112911, 112923, 113423, 114301, 114321, 114336, 114349, 114402, 114413, 114426, 114528, 114550, 115547, 115602, 115616, 115627, 115641, 115655, 120050, 120101, 120114, 120127, 120140, 120151, 120203, 120215, 120234, 120248, 120259, 120319, 120430, 120545, 120605, 120620, 120633, 120652, 120708, 120723, 120726, 120736, 120756, 120808, 120848, 120855, 120911, 120926, 120933, 120949, 120954</li><li>最后更新：2026-04-20</li><li>适合查询：官方怎么定义素材、广播是什么、自定义组件是什么、UI 如何分类、为什么切换 UI 时找不到做好的 UI、为什么会出现两个重叠的 UI、为什么互动按钮不显示、为什么角色在地图上走不动、碰撞盒和阻挡通行怎么排查、为什么改了素材属性地图里没变化、素材和地图物体是什么关系、配置表与变量表怎么区分、玩家变量表改了为什么老用户不生效、局部变量怎么用、坐标和向量怎么理解、地图与 UI 坐标转换怎么应用、执行指令与属性设置怎么用、判断/循环/等待怎么用、渐变和触发事件怎么理解、黄色语句和蓝色语句有什么区别、退出脚本怎么提前结束流程、玩家丢失后怎么重新添加、如何用时间戳计算未登录天数、怎么做玩家首次登录、卡牌拖拽放置涉及什么、开始录屏和结束录屏怎么用、录屏权限请求是什么、地图组件和联机设置有哪些历史变化、货币组件和货币条怎么工作、近战武器和角色组件有哪些关键属性、背包组件和背包容量怎么控制、移动摇杆/普通摇杆/技能摇杆有什么区别、快捷聊天按钮有什么用、快捷聊天按钮和输入框有什么区别、输入框怎么拿到玩家输入、弹簧组件怎么触发、屏幕震动/设置音量/播放音效/BGM/手机振动/复制到剪切板怎么用、官方教程栏目有哪些、基础知识栏目里都有哪些条目、常见问题和实用功能里都有哪些专题</li></ul><h2 id="快速导航" tabindex="-1">快速导航 <a class="header-anchor" href="#快速导航" aria-label="Permalink to “快速导航”">​</a></h2><ul><li><p><a href="#_1-广播">1. 广播</a></p></li><li><p><a href="#_2-自定义组件">2. 自定义组件</a></p></li><li><p><a href="#_3-素材">3. 素材</a></p></li><li><p><a href="#_4-素材的基础操作">4. 素材的基础操作</a></p></li><li><p><a href="#_6-配置表与变量表">6. 配置表与变量表</a></p></li><li><p><a href="#_7-脚本语句基础知识">7. 脚本语句基础知识</a></p></li><li><p><a href="#_8-坐标与向量">8. 坐标与向量</a></p></li><li><p><a href="#_9-玩家变量表同步与-ui-切换常见问题">9. 玩家变量表同步与 UI 切换常见问题</a></p></li><li><p><a href="#_10-局部变量与属性">10. 局部变量与属性</a></p></li><li><p><a href="#_11-执行指令语句">11. 执行指令语句</a></p></li><li><p><a href="#_12-脚本控制流与事件语句">12. 脚本控制流与事件语句</a></p></li><li><p><a href="#_13-编辑器常见操作与时间系统">13. 编辑器常见操作与时间系统</a></p></li><li><p><a href="#_14-首次登录与官方问题库结构">14. 首次登录与官方问题库结构</a></p></li><li><p><a href="#_15-常见问题补强ui碰撞与实例化">15. 常见问题补强：UI、碰撞与实例化</a></p></li><li><p><a href="#_16-实用功能补强卡牌拖拽放置与坐标转换">16. 实用功能补强：卡牌拖拽放置与坐标转换</a></p></li><li><p><a href="#_18-基础知识栏目细化">18. 基础知识栏目细化</a></p></li><li><p><a href="#_20-噪声页与低价值相邻页处理原则">20. 噪声页与低价值相邻页处理原则</a></p></li><li><p><a href="#_21-地图货币与战斗基础组件补充">21. 地图、货币与战斗基础组件补充</a></p></li><li><p><a href="#_22-ui-输入组件与背包系统补充">22. UI 输入组件与背包系统补充</a></p></li><li><p><a href="#_23-表现与设备能力指令补充">23. 表现与设备能力指令补充</a></p></li><li><p><a href="#_24-配置表属性与指令补强">24. 配置表属性与指令补强</a></p></li><li><p><a href="#_26-聊天交互组件补充">26. 聊天交互组件补充</a></p></li><li><p><a href="#_27-战斗道具与生命系统补充">27. 战斗、道具与生命系统补充</a></p></li><li><p><a href="#_28-商业化商店与排行榜系统补充">28. 商业化、商店与排行榜系统补充</a></p></li><li><p><a href="#_29-数字真假值文本数组与配置表知识树补充">29. 数字、真假值、文本、数组与配置表知识树补充</a></p></li><li><p><a href="#_31-官方教程系统总览对象组件脚本ui数据之间的关系">31. 官方教程系统总览</a></p></li><li><p><a href="#_32-ui-系统专题总表">32. UI 系统专题总表</a></p></li><li><p><a href="#_33-战斗系统专题总表">33. 战斗系统专题总表</a></p></li><li><p><a href="#_34-数据与脚本系统专题总表">34. 数据与脚本系统专题总表</a></p></li><li><p><a href="#_35-常见问题与实用功能专题导航">35. 常见问题与实用功能专题导航</a></p></li></ul><h2 id="证据层与知识层的对应关系" tabindex="-1">证据层与知识层的对应关系 <a class="header-anchor" href="#证据层与知识层的对应关系" aria-label="Permalink to “证据层与知识层的对应关系”">​</a></h2><ul><li><code>docs/OCR资料/官方教程截图转文本索引.md</code>：偏 <strong>逐页证据层</strong>，保留截图编号、原始 OCR 摘录、补证页与噪声页信息。</li><li><code>docs/教程资料/官方教程知识索引.md</code>：偏 <strong>主题聚合层</strong>，把多个截图中的同一主题合并为更适合检索与问答的知识条目。</li><li>整理原则： <ul><li>同一主题若有多张截图，优先在知识索引中合并描述，在 OCR 索引中保留编号链。</li><li>目录页、导航页、无文本页、评论噪声页主要保留在 OCR 索引中作证据占位。</li><li>若后续继续拆专题文档，应以知识索引为入口、以 OCR 索引作回链证据。</li></ul></li></ul><h2 id="_1-广播" tabindex="-1">1. 广播 <a class="header-anchor" href="#_1-广播" aria-label="Permalink to “1. 广播”">​</a></h2><h3 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to “主题”">​</a></h3><p>什么是广播？</p><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to “核心概念”">​</a></h3><ul><li>广播是一种将事件或消息发送给多个监听者的机制。</li><li>发送者不需要知道监听者的具体信息。</li><li>监听者通过订阅事件来接收并响应消息。</li></ul><h3 id="类比理解" tabindex="-1">类比理解 <a class="header-anchor" href="#类比理解" aria-label="Permalink to “类比理解”">​</a></h3><ul><li>类似现实中的电台广播。</li><li>发送者相当于电台。</li><li>所有调到对应频道的接收者都可以收到信号。</li></ul><h3 id="典型应用场景" tabindex="-1">典型应用场景 <a class="header-anchor" href="#典型应用场景" aria-label="Permalink to “典型应用场景”">​</a></h3><ul><li>玩家行为触发：例如玩家死亡时，通知 UI、敌人系统、成就系统等。</li><li>游戏状态变化：例如关卡加载完成、暂停游戏、分数更新等全局事件。</li><li>对象交互：例如敌人被击败时，通知任务系统、掉落物系统等。</li></ul><h3 id="对-ai-的可用标签" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>事件系统</li><li>消息分发</li><li>解耦通信</li><li>广播机制</li><li>游戏逻辑通知</li></ul><hr><h2 id="_2-自定义组件" tabindex="-1">2. 自定义组件 <a class="header-anchor" href="#_2-自定义组件" aria-label="Permalink to “2. 自定义组件”">​</a></h2><h3 id="主题-1" tabindex="-1">主题 <a class="header-anchor" href="#主题-1" aria-label="Permalink to “主题”">​</a></h3><p>什么是自定义组件？</p><h3 id="核心概念-1" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念-1" aria-label="Permalink to “核心概念”">​</a></h3><ul><li>自定义组件是由创作者自己编写和定义的组件。</li><li>创作者可以自行定义组件内部的属性、指令、触发时机与行为逻辑。</li></ul><h3 id="好处" tabindex="-1">好处 <a class="header-anchor" href="#好处" aria-label="Permalink to “好处”">​</a></h3><ul><li>满足官方内置组件无法覆盖的特定需求。</li><li>可以记录物体状态、扩展物体行为和功能。</li><li>可以提高重复利用性，把某种功能抽象为可复用组件。</li></ul><h3 id="示例理解" tabindex="-1">示例理解 <a class="header-anchor" href="#示例理解" aria-label="Permalink to “示例理解”">​</a></h3><ul><li>例如做一棵可以互动的树： <ul><li>需要记录树是否被砍倒</li><li>需要记录再次生长时间</li><li>需要控制掉落木头等信息</li></ul></li><li>这类需求往往无法只靠官方固定组件完成，因此需要自定义组件。</li></ul><h3 id="复用价值" tabindex="-1">复用价值 <a class="header-anchor" href="#复用价值" aria-label="Permalink to “复用价值”">​</a></h3><ul><li>当某个功能被封装为完整的自定义组件后，其他物体只要挂载该组件，就可以复用同一套功能。</li></ul><h3 id="对-ai-的可用标签-1" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-1" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>组件系统</li><li>自定义逻辑</li><li>可复用功能</li><li>状态记录</li><li>行为封装</li></ul><hr><h2 id="_3-素材" tabindex="-1">3. 素材 <a class="header-anchor" href="#_3-素材" aria-label="Permalink to “3. 素材”">​</a></h2><h3 id="主题-2" tabindex="-1">主题 <a class="header-anchor" href="#主题-2" aria-label="Permalink to “主题”">​</a></h3><p>什么是素材？</p><h3 id="基本定义" tabindex="-1">基本定义 <a class="header-anchor" href="#基本定义" aria-label="Permalink to “基本定义”">​</a></h3><ul><li>在创游引擎中，素材不是物体。</li><li>当素材被摆放到地图中后，会成为物体（object）。</li><li>素材和物体在引擎中的图标与概念不同。</li></ul><h3 id="地图素材分类" tabindex="-1">地图素材分类 <a class="header-anchor" href="#地图素材分类" aria-label="Permalink to “地图素材分类”">​</a></h3><p>地图素材分为六种类型：</p><ul><li>地块</li><li>装饰</li><li>角色</li><li>装置</li><li>道具</li><li>武器</li></ul><h3 id="ui-素材分类" tabindex="-1">UI 素材分类 <a class="header-anchor" href="#ui-素材分类" aria-label="Permalink to “UI 素材分类”">​</a></h3><ul><li>UI 素材单独成类。</li><li>OCR 中可识别到 UI 相关素材包括：按钮、输入框、勾选按钮、滑动条、进度条、摇杆、互动按钮、武器道具摇杆、技能摇杆、跳跃按钮、移动摇杆、货币条等。</li></ul><h3 id="各类素材的作用摘要" tabindex="-1">各类素材的作用摘要 <a class="header-anchor" href="#各类素材的作用摘要" aria-label="Permalink to “各类素材的作用摘要”">​</a></h3><h4 id="地块" tabindex="-1">地块 <a class="header-anchor" href="#地块" aria-label="Permalink to “地块”">​</a></h4><ul><li>常用于整体地面铺设。</li><li>处于显示层级较底的位置。</li><li>适合构建山川湖泊、园林庭院、街道场景等整体氛围。</li></ul><h4 id="装饰" tabindex="-1">装饰 <a class="header-anchor" href="#装饰" aria-label="Permalink to “装饰”">​</a></h4><ul><li>用于环境点缀。</li><li>例如云朵、远山、室内挂画等。</li></ul><h4 id="角色" tabindex="-1">角色 <a class="header-anchor" href="#角色" aria-label="Permalink to “角色”">​</a></h4><ul><li>表示具有阵营或身份的游戏角色。</li><li>例如主角、NPC、敌人、怪物等。</li></ul><h4 id="装置" tabindex="-1">装置 <a class="header-anchor" href="#装置" aria-label="Permalink to “装置”">​</a></h4><ul><li>指具有功能性的素材。</li><li>例如圆锯、火球、地刺、炸弹、按钮、告示牌、怪物门等。</li><li>除官方内置装置外，也可以自行定义装置。</li></ul><h4 id="道具" tabindex="-1">道具 <a class="header-anchor" href="#道具" aria-label="Permalink to “道具”">​</a></h4><ul><li>可拾取的物品。</li><li>例如血瓶、经验球、金币等。</li></ul><h4 id="武器" tabindex="-1">武器 <a class="header-anchor" href="#武器" aria-label="Permalink to “武器”">​</a></h4><ul><li>手持并可产生伤害的对象。</li><li>包括近战与远程武器，例如刀剑、枪械、法杖等。</li></ul><h3 id="素材与功能的关系" tabindex="-1">素材与功能的关系 <a class="header-anchor" href="#素材与功能的关系" aria-label="Permalink to “素材与功能的关系”">​</a></h3><ul><li>素材本身不一定天然带有实际功能。</li><li>素材摆放在地图中后，只有添加相应组件，才会具备理想能力。</li><li>官方内置素材通常已经提前组装了所需组件。</li><li>自制素材则需要创作者自己选择并挂载合适组件。</li></ul><h3 id="重要说明" tabindex="-1">重要说明 <a class="header-anchor" href="#重要说明" aria-label="Permalink to “重要说明”">​</a></h3><ul><li>不同类型的素材可添加的组件并不相同。</li><li>因此素材类型会直接影响后续可实现的功能范围。</li></ul><h3 id="对-ai-的可用标签-2" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-2" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>素材系统</li><li>物体 object</li><li>地图素材</li><li>UI 素材</li><li>组件挂载</li><li>对象功能组装</li></ul><hr><h2 id="_4-素材的基础操作" tabindex="-1">4. 素材的基础操作 <a class="header-anchor" href="#_4-素材的基础操作" aria-label="Permalink to “4. 素材的基础操作”">​</a></h2><h3 id="主题-3" tabindex="-1">主题 <a class="header-anchor" href="#主题-3" aria-label="Permalink to “主题”">​</a></h3><p>素材的基础操作</p><h3 id="核心定义" tabindex="-1">核心定义 <a class="header-anchor" href="#核心定义" aria-label="Permalink to “核心定义”">​</a></h3><ul><li>素材是【贴图】与【各种组件】的组合体。</li></ul><h3 id="导入素材" tabindex="-1">导入素材 <a class="header-anchor" href="#导入素材" aria-label="Permalink to “导入素材”">​</a></h3><ul><li>每个大类素材栏最左边的蓝色 <code>+</code> 是导入素材的入口。</li><li>OCR 中提到导入素材有四种方式，但当前截图片段未完整展示四种具体方式，后续需要继续补录。</li></ul><h3 id="可进一步补全的内容" tabindex="-1">可进一步补全的内容 <a class="header-anchor" href="#可进一步补全的内容" aria-label="Permalink to “可进一步补全的内容”">​</a></h3><p>建议后续继续从截图中抽取以下子主题：</p><ul><li>四种导入方式的完整说明</li><li>素材创建流程</li><li>贴图与组件之间的关系</li><li>自制素材与内置素材的差异</li></ul><h3 id="对-ai-的可用标签-3" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-3" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>素材导入</li><li>贴图</li><li>组件组合</li><li>基础操作</li><li>编辑器入口</li></ul><hr><h2 id="_5-当前已识别的教程主题清单" tabindex="-1">5. 当前已识别的教程主题清单 <a class="header-anchor" href="#_5-当前已识别的教程主题清单" aria-label="Permalink to “5. 当前已识别的教程主题清单”">​</a></h2><p>目前从抽样截图中已识别出的教程主题包括：</p><ul><li>什么是广播</li><li>什么是自定义组件</li><li>什么是素材</li><li>素材的基础操作</li><li>UI 素材分类</li></ul><p>这些主题可作为后续在原图恢复后继续 OCR、以及当前阶段继续去重、归类和知识图谱构建的初始索引。</p><hr><h2 id="_6-配置表与变量表" tabindex="-1">6. 配置表与变量表 <a class="header-anchor" href="#_6-配置表与变量表" aria-label="Permalink to “6. 配置表与变量表”">​</a></h2><h3 id="主题-4" tabindex="-1">主题 <a class="header-anchor" href="#主题-4" aria-label="Permalink to “主题”">​</a></h3><p>配置表、变量表、表结构的区别</p><h3 id="核心概念-2" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念-2" aria-label="Permalink to “核心概念”">​</a></h3><ul><li><code>表结构</code>：定义一行数据有哪些字段、字段类型是什么。</li><li><code>配置表</code>：静态数据，通常在设计阶段预先写好，用于承载规则、参数、策划数据。</li><li><code>变量表</code>：动态数据，通常在运行过程中随玩家行为变化，用于承载状态、进度、库存等。</li></ul><h3 id="关键边界" tabindex="-1">关键边界 <a class="header-anchor" href="#关键边界" aria-label="Permalink to “关键边界”">​</a></h3><ul><li>配置表更像“规则库”。</li><li>变量表更像“运行中的状态记录”。</li><li>运行中即使改了配置表，也通常只对当前运行过程生效，不会改写原始配置内容。</li></ul><h3 id="配置表属性与指令" tabindex="-1">配置表属性与指令 <a class="header-anchor" href="#配置表属性与指令" aria-label="Permalink to “配置表属性与指令”">​</a></h3><p>当前可确认的配置表能力包括：</p><ul><li>属性： <ul><li>总行数</li><li>第n行</li><li>名为xx的行</li><li>是否存在某行</li></ul></li><li>指令： <ul><li>添加一行</li><li>从表中移除第n行</li><li>从表中移除名为xx的行</li></ul></li></ul><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h3><ul><li>直接读取不存在的第 n 行会报错。</li><li>通过行名读取不存在的行也会报错。</li><li>更稳妥的写法是先判断 <code>是否存在某行</code>。</li></ul><h3 id="对-ai-的可用标签-4" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-4" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>配置表</li><li>变量表</li><li>表结构</li><li>数据管理</li><li>静态配置</li><li>动态状态</li><li>配表系统</li></ul><hr><h2 id="_7-脚本语句基础知识" tabindex="-1">7. 脚本语句基础知识 <a class="header-anchor" href="#_7-脚本语句基础知识" aria-label="Permalink to “7. 脚本语句基础知识”">​</a></h2><h3 id="主题-5" tabindex="-1">主题 <a class="header-anchor" href="#主题-5" aria-label="Permalink to “主题”">​</a></h3><p>黄色语句、蓝色语句与执行时序</p><h3 id="核心概念-3" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念-3" aria-label="Permalink to “核心概念”">​</a></h3><ul><li>每个脚本语句都是为了实现某种功能或行为。</li><li>复杂脚本并不是靠单个神奇指令，而是靠多条基础语句组合出来的。</li><li>官方特别强调了“语句颜色”对应的执行方式差异。</li></ul><h3 id="黄色与蓝色语句的区别" tabindex="-1">黄色与蓝色语句的区别 <a class="header-anchor" href="#黄色与蓝色语句的区别" aria-label="Permalink to “黄色与蓝色语句的区别”">​</a></h3><ul><li><code>黄色语句</code>：会阻塞整个脚本流程，只有当前语句完成后，后面的语句才会继续执行。</li><li><code>蓝色语句</code>：不会阻塞当前脚本，执行到这里后，后续语句可以立即继续。</li><li>某些语句支持在黄色/蓝色之间切换，通常通过语句前方的转换图标完成。</li></ul><h3 id="实际意义" tabindex="-1">实际意义 <a class="header-anchor" href="#实际意义" aria-label="Permalink to “实际意义”">​</a></h3><ul><li>黄色写法适合需要严格顺序的流程，比如先等待、再执行下一步。</li><li>蓝色写法适合制造“同时进行”的效果，比如一边渐变颜色、一边缩放、一边执行其他动作。</li><li>这也是理解“为什么同样几条语句，执行效果完全不一样”的关键。</li></ul><h3 id="对-ai-的可用标签-5" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-5" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>脚本基础</li><li>阻塞执行</li><li>非阻塞执行</li><li>黄色语句</li><li>蓝色语句</li><li>时序控制</li></ul><hr><h2 id="_8-坐标与向量" tabindex="-1">8. 坐标与向量 <a class="header-anchor" href="#_8-坐标与向量" aria-label="Permalink to “8. 坐标与向量”">​</a></h2><h3 id="主题-6" tabindex="-1">主题 <a class="header-anchor" href="#主题-6" aria-label="Permalink to “主题”">​</a></h3><p>坐标、向量、空间运算</p><h3 id="基本定义-1" tabindex="-1">基本定义 <a class="header-anchor" href="#基本定义-1" aria-label="Permalink to “基本定义”">​</a></h3><ul><li><code>坐标</code>：表示一个点在空间中的位置。</li><li><code>向量</code>：表示一个具有大小和方向的量，可用于位移、速度、力等。</li><li>创游是 <code>2D 引擎</code>，所以主要围绕二维坐标与二维向量展开。</li></ul><h3 id="关键规则" tabindex="-1">关键规则 <a class="header-anchor" href="#关键规则" aria-label="Permalink to “关键规则”">​</a></h3><ul><li>地图坐标原点 <code>(0,0)</code> 在左下角。</li><li>不能把手机屏幕左下角直接当成地图原点。</li><li><code>相对父物体坐标</code> 的原点是父物体中心点。</li><li>坐标和向量都常写作 <code>(a,b)</code>，但语义不同： <ul><li>坐标说的是“在哪”；</li><li>向量说的是“往哪、多少”。</li></ul></li></ul><h3 id="可确认的属性与运算" tabindex="-1">可确认的属性与运算 <a class="header-anchor" href="#可确认的属性与运算" aria-label="Permalink to “可确认的属性与运算”">​</a></h3><ul><li>分量属性： <ul><li>x分量</li><li>y分量</li></ul></li><li>向量相关属性： <ul><li>向量角度</li><li>向量长度</li><li>与另一向量的夹角</li><li>旋转向量</li></ul></li><li>运算： <ul><li>加</li><li>减</li><li>乘</li><li>除</li></ul></li><li>运算规则：按分量分别计算。</li></ul><h3 id="应用理解" tabindex="-1">应用理解 <a class="header-anchor" href="#应用理解" aria-label="Permalink to “应用理解”">​</a></h3><p>适合用于：</p><ul><li>位置偏移</li><li>子弹与技能方向</li><li>UI / 物体相对位置</li><li>朝向计算</li><li>散射弹幕与旋转轨迹</li></ul><h3 id="对-ai-的可用标签-6" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-6" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>坐标</li><li>向量</li><li>二维空间</li><li>相对坐标</li><li>向量长度</li><li>向量角度</li><li>空间运算</li></ul><hr><h2 id="_9-玩家变量表同步与-ui-切换常见问题" tabindex="-1">9. 玩家变量表同步与 UI 切换常见问题 <a class="header-anchor" href="#_9-玩家变量表同步与-ui-切换常见问题" aria-label="Permalink to “9. 玩家变量表同步与 UI 切换常见问题”">​</a></h2><h3 id="主题-7" tabindex="-1">主题 <a class="header-anchor" href="#主题-7" aria-label="Permalink to “主题”">​</a></h3><p>老用户数据不同步、切换 UI 找不到目标 UI</p><h3 id="玩家变量表同步" tabindex="-1">玩家变量表同步 <a class="header-anchor" href="#玩家变量表同步" aria-label="Permalink to “玩家变量表同步”">​</a></h3><ul><li>如果直接修改 <code>玩家变量表</code> 的结构或默认数据，已经存在旧存档/云存档的玩家通常不会自动同步。</li><li>老用户继续读取的是自己的旧数据，不会因为你改了编辑器里的表就自动刷新。</li><li>官方建议在 <code>玩家开始时</code> 或等效入口脚本里做一次同步补丁。</li><li>同步思路通常是： <ul><li>检查某行、某字段、某结构是否存在；</li><li>如果不存在，就补加默认值；</li><li>如果存在，就保留原有用户数据。</li></ul></li><li>更偏静态的策划参数，应优先写在 <code>配置表</code> 而不是 <code>玩家变量表</code>。</li></ul><h3 id="ui-切换常见问题" tabindex="-1">UI 切换常见问题 <a class="header-anchor" href="#ui-切换常见问题" aria-label="Permalink to “UI 切换常见问题”">​</a></h3><ul><li>创游 UI 至少分为： <ul><li>地图 UI</li><li>操作 UI</li><li>物体 UI</li></ul></li><li>这三类 UI 的切换指令位置不同。</li><li>如果“明明做了 UI 却找不到”，通常不是 UI 消失了，而是用了错误类别下的切换指令。</li><li><code>物体 UI</code> 还需要先挂对应组件，否则相关切换指令不会出现。</li></ul><h3 id="对-ai-的可用标签-7" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-7" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>玩家变量表</li><li>数据同步</li><li>老存档兼容</li><li>配置表</li><li>UI 切换</li><li>地图UI</li><li>操作UI</li><li>物体UI</li><li>常见问题</li></ul><hr><h2 id="_10-局部变量与属性" tabindex="-1">10. 局部变量与属性 <a class="header-anchor" href="#_10-局部变量与属性" aria-label="Permalink to “10. 局部变量与属性”">​</a></h2><h3 id="主题-8" tabindex="-1">主题 <a class="header-anchor" href="#主题-8" aria-label="Permalink to “主题”">​</a></h3><p>变量系统基础：局部变量、属性、设置语句</p><h3 id="局部变量" tabindex="-1">局部变量 <a class="header-anchor" href="#局部变量" aria-label="Permalink to “局部变量”">​</a></h3><ul><li>新建局部变量时，需要指定： <ul><li>变量名</li><li>初始值</li></ul></li><li>初始值会决定变量类型。</li><li>当前可确认局部变量至少可承载： <ul><li>数字</li><li>真假值</li><li>文本</li><li>物体</li><li>坐标/向量</li><li>以及其他返回值类型</li></ul></li></ul><h3 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to “属性”">​</a></h3><p>当前可确认有四类“设置属性”语句：</p><ul><li>设置自身属性</li><li>设置系统属性</li><li>设置当前地图属性</li><li>设置玩家属性</li></ul><h3 id="统一理解" tabindex="-1">统一理解 <a class="header-anchor" href="#统一理解" aria-label="Permalink to “统一理解”">​</a></h3><ul><li>所有以 <code>设置...为...</code> 开头的语句，本质上都在修改某个变量/属性的值。</li><li>可以粗略理解为： <ul><li><code>属性 ≈ 挂在某个主体上的变量</code></li></ul></li><li>但不是所有属性都可改，只有可变属性才能放进设置语句。</li></ul><h3 id="对-ai-的可用标签-8" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-8" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>局部变量</li><li>属性</li><li>设置语句</li><li>变量类型</li><li>自身属性</li><li>系统属性</li><li>地图属性</li><li>玩家属性</li></ul><hr><h2 id="_11-执行指令语句" tabindex="-1">11. 执行指令语句 <a class="header-anchor" href="#_11-执行指令语句" aria-label="Permalink to “11. 执行指令语句”">​</a></h2><h3 id="主题-9" tabindex="-1">主题 <a class="header-anchor" href="#主题-9" aria-label="Permalink to “主题”">​</a></h3><p>如何真正调用指令</p><h3 id="核心概念-4" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念-4" aria-label="Permalink to “核心概念”">​</a></h3><ul><li>指令是组件的一部分。</li><li>指令不会自动执行。</li><li>只有通过 <code>执行指令</code> 语句调用后，指令才会真正生效。</li></ul><h3 id="当前可确认的主体" tabindex="-1">当前可确认的主体 <a class="header-anchor" href="#当前可确认的主体" aria-label="Permalink to “当前可确认的主体”">​</a></h3><p>创游提供了至少四类执行指令语句：</p><ul><li>执行自身指令</li><li>执行当前地图指令</li><li>执行系统指令</li><li>执行玩家指令</li></ul><h3 id="执行模型" tabindex="-1">执行模型 <a class="header-anchor" href="#执行模型" aria-label="Permalink to “执行模型”">​</a></h3><ul><li>执行指令可以是阻塞的。</li><li>也可以是非阻塞的。</li><li>这和黄色语句 / 蓝色语句的区别直接相关。</li></ul><h3 id="重要意义" tabindex="-1">重要意义 <a class="header-anchor" href="#重要意义" aria-label="Permalink to “重要意义”">​</a></h3><p>这说明创游脚本不只是“单物体行为编排”，还支持：</p><ul><li>物体级调用</li><li>地图级调用</li><li>系统级调用</li><li>玩家级调用</li></ul><h3 id="对-ai-的可用标签-9" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-9" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>执行指令</li><li>指令调用</li><li>阻塞执行</li><li>非阻塞执行</li><li>自身指令</li><li>地图指令</li><li>系统指令</li><li>玩家指令</li></ul><hr><h2 id="_12-脚本控制流与事件语句" tabindex="-1">12. 脚本控制流与事件语句 <a class="header-anchor" href="#_12-脚本控制流与事件语句" aria-label="Permalink to “12. 脚本控制流与事件语句”">​</a></h2><h3 id="主题-10" tabindex="-1">主题 <a class="header-anchor" href="#主题-10" aria-label="Permalink to “主题”">​</a></h3><p>渐变、触发事件、判断、循环、等待、概率执行、退出脚本</p><h3 id="渐变语句" tabindex="-1">渐变语句 <a class="header-anchor" href="#渐变语句" aria-label="Permalink to “渐变语句”">​</a></h3><ul><li>用于让某个属性在一段时间内过渡到目标值。</li><li>关键参数至少包括： <ul><li>时间</li><li>属性</li><li>渐变曲线</li><li>变化后的值</li></ul></li><li>属性主体不局限于物体自身，也可以是系统、地图、玩家。</li><li>渐变曲线会影响速度变化方式。</li><li>渐变语句可以是阻塞，也可以是非阻塞。</li></ul><h3 id="触发事件语句" tabindex="-1">触发事件语句 <a class="header-anchor" href="#触发事件语句" aria-label="Permalink to “触发事件语句”">​</a></h3><ul><li>只在编辑自定义组件时出现。</li><li>作用是主动触发某个事件，让该事件下方绑定的脚本开始执行。</li><li>可与 <code>当点击时 / 当物体开始时 / 当死亡时</code> 这类事件模型联动。</li></ul><h3 id="判断语句" tabindex="-1">判断语句 <a class="header-anchor" href="#判断语句" aria-label="Permalink to “判断语句”">​</a></h3><ul><li>本质是 <code>如果条件成立，执行A，否则执行B</code>。</li><li>是兑换码、商店判断、游戏结算、奖励分发等逻辑的基础。</li><li>常与真假值、关系运算、局部变量配合使用。</li></ul><h3 id="循环语句" tabindex="-1">循环语句 <a class="header-anchor" href="#循环语句" aria-label="Permalink to “循环语句”">​</a></h3><p>当前可确认至少包括：</p><ul><li>无限循环</li><li>保持循环直到</li><li>循环x次</li><li>计数循环</li><li>遍历循环</li><li>跳出循环</li><li>跳过本次循环</li></ul><p>关键注意事项：</p><ul><li>无限循环数量过多会拖慢游戏。</li><li>广播里滥用无限循环容易制造越来越多常驻脚本。</li><li>嵌套循环会快速提高复杂度。</li><li>不要在循环体内修改循环变量。</li><li>不要在遍历循环时改正在遍历的数组。</li><li>重计算尽量外提到局部变量中，避免每圈重复算。</li></ul><h3 id="等待语句" tabindex="-1">等待语句 <a class="header-anchor" href="#等待语句" aria-label="Permalink to “等待语句”">​</a></h3><ul><li>等待语句是阻塞语句，不能转成蓝色异步语句。</li><li>当前可确认有两种： <ul><li>计时等待</li><li>条件等待</li></ul></li><li>条件等待会一直卡住，直到条件变成真。</li></ul><h3 id="概率执行与退出脚本" tabindex="-1">概率执行与退出脚本 <a class="header-anchor" href="#概率执行与退出脚本" aria-label="Permalink to “概率执行与退出脚本”">​</a></h3><ul><li><code>概率执行</code>：按概率决定是否执行某段逻辑，也可给出剩余概率分支。</li><li><code>退出脚本</code>：用于提前结束当前脚本，不再继续执行后续语句。</li></ul><h3 id="对-ai-的可用标签-10" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-10" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>控制流</li><li>判断语句</li><li>循环语句</li><li>等待语句</li><li>渐变语句</li><li>触发事件</li><li>概率执行</li><li>退出脚本</li><li>脚本性能</li></ul><hr><h2 id="_13-编辑器常见操作与时间系统" tabindex="-1">13. 编辑器常见操作与时间系统 <a class="header-anchor" href="#_13-编辑器常见操作与时间系统" aria-label="Permalink to “13. 编辑器常见操作与时间系统”">​</a></h2><h3 id="主题-11" tabindex="-1">主题 <a class="header-anchor" href="#主题-11" aria-label="Permalink to “主题”">​</a></h3><p>添加玩家、时间戳、帮助中心入口</p><h3 id="添加玩家" tabindex="-1">添加玩家 <a class="header-anchor" href="#添加玩家" aria-label="Permalink to “添加玩家”">​</a></h3><ul><li>如果地图上的玩家角色被误删，可以重新添加。</li><li>当前可确认操作路径： <ul><li>切换素材到 <code>角色</code></li><li>点击右下角 <code>添加玩家</code></li></ul></li><li>这说明玩家对象在编辑器里归属于角色体系下的可放置对象。</li><li>这类知识非常适合归入“常见问题 / 编辑器补救操作”。</li></ul><h3 id="时间戳与未登录天数" tabindex="-1">时间戳与未登录天数 <a class="header-anchor" href="#时间戳与未登录天数" aria-label="Permalink to “时间戳与未登录天数”">​</a></h3><ul><li>时间戳是用数字表示某一时刻的统一时间标准。</li><li>它的优势包括： <ul><li>统一时区标准</li><li>方便直接相减计算时间差</li><li>更适合程序保存和计算</li></ul></li><li>一个可确认的典型应用是：<code>计算玩家未登录游戏的天数</code>。</li><li>官方思路可以概括为： <ol><li>取当前服务器时间戳；</li><li>读取玩家上次登录时间戳；</li><li>两者相减得到时间差；</li><li>除以一天的毫秒数并向下取整，得到天数；</li><li>更新本次登录时间。</li></ol></li><li>图中还提示 <code>登录时间</code> 应存入玩家变量并勾选云存储，因此这是一个： <ul><li>玩家级数据</li><li>持久化数据</li><li>适合做签到、回归奖励、离线时长判断的数据点</li></ul></li></ul><h3 id="官方教程栏目结构" tabindex="-1">官方教程栏目结构 <a class="header-anchor" href="#官方教程栏目结构" aria-label="Permalink to “官方教程栏目结构”">​</a></h3><ul><li>当前可确认官方教程/帮助中心至少包含以下栏目： <ul><li>基础知识</li><li>组件百科</li><li>指令百科</li><li>成套教程</li><li>脚本解析</li><li>常见问题</li><li>实用功能</li><li>帮助中心</li></ul></li><li>还能看到 <code>手把手教你做… / 入门</code> 之类的入门教程入口。</li><li>这说明官方知识体系是栏目化组织，而不只是零散帖子。</li></ul><h3 id="对-ai-的可用标签-11" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-11" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>添加玩家</li><li>编辑器常见问题</li><li>角色素材</li><li>时间戳</li><li>未登录天数</li><li>玩家变量</li><li>云存储</li><li>帮助中心</li><li>官方教程栏目</li></ul><hr><h2 id="_14-首次登录与官方问题库结构" tabindex="-1">14. 首次登录与官方问题库结构 <a class="header-anchor" href="#_14-首次登录与官方问题库结构" aria-label="Permalink to “14. 首次登录与官方问题库结构”">​</a></h2><h3 id="主题-12" tabindex="-1">主题 <a class="header-anchor" href="#主题-12" aria-label="Permalink to “主题”">​</a></h3><p>首次登录一次性逻辑、常见问题入口、实用功能入口</p><h3 id="首次登录的一次性逻辑" tabindex="-1">首次登录的一次性逻辑 <a class="header-anchor" href="#首次登录的一次性逻辑" aria-label="Permalink to “首次登录的一次性逻辑”">​</a></h3><ul><li>官方给出的最简洁方案是：使用一个 <code>玩家变量</code> 来记录“是否首次登录”。</li><li>这个变量适合使用： <ul><li><code>真假值类型</code></li><li><code>勾选云存储</code></li></ul></li><li>典型实现流程： <ol><li>玩家进入时读取 <code>首次登录</code> 变量；</li><li>若为真，则发放开服礼包或首次奖励；</li><li>执行完奖励后，把该变量改成假；</li><li>后续再次登录时，就不会重复触发。</li></ol></li><li>这种写法不仅适用于登录礼包，也适用于： <ul><li>首次进入地图</li><li>首次触发剧情</li><li>首次解锁功能提示</li><li>新手引导只执行一次</li></ul></li></ul><h3 id="常见问题栏目结构" tabindex="-1">常见问题栏目结构 <a class="header-anchor" href="#常见问题栏目结构" aria-label="Permalink to “常见问题栏目结构”">​</a></h3><ul><li>官方帮助体系中存在独立的 <code>常见问题</code> 栏目。</li><li>当前从目录页可识别出的高频问题方向包括： <ul><li>如何添加玩家</li><li>为什么表改了之后不生效</li><li>为什么切换 UI 时找不到做好的 UI</li><li>碰撞盒与阻挡通行</li><li>角色走不动</li><li>互动按钮不显示</li><li>素材与地图中的物体区别</li><li>切换地图 / 联机 / 玩家变量相关问题</li></ul></li><li>这说明官方不仅提供概念教程，也持续沉淀高频踩坑问题的答疑库。</li></ul><h3 id="实用功能栏目结构" tabindex="-1">实用功能栏目结构 <a class="header-anchor" href="#实用功能栏目结构" aria-label="Permalink to “实用功能栏目结构”">​</a></h3><ul><li>官方帮助体系中还存在独立的 <code>实用功能</code> 栏目。</li><li>当前可识别出的功能实现主题包括： <ul><li>计算玩家未登录天数</li><li>怎么做玩家首次登录</li><li>卡牌拖拽放置</li></ul></li><li>这说明官方教程已经开始把“怎么做某个功能”整理成方案型知识，而不只是组件百科或脚本术语解释。</li></ul><h3 id="对-ai-的可用标签-12" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-12" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>首次登录</li><li>玩家变量</li><li>云存储</li><li>开服礼包</li><li>常见问题</li><li>实用功能</li><li>教程目录</li><li>问题库</li><li>功能实现</li></ul><hr><h2 id="_15-常见问题补强-ui、碰撞与实例化" tabindex="-1">15. 常见问题补强：UI、碰撞与实例化 <a class="header-anchor" href="#_15-常见问题补强-ui、碰撞与实例化" aria-label="Permalink to “15. 常见问题补强：UI、碰撞与实例化”">​</a></h2><h3 id="主题-13" tabindex="-1">主题 <a class="header-anchor" href="#主题-13" aria-label="Permalink to “主题”">​</a></h3><p>UI 重叠、互动按钮不显示、角色走不动、素材改了地图里却没变</p><h3 id="ui-重叠与默认操作ui" tabindex="-1">UI 重叠与默认操作UI <a class="header-anchor" href="#ui-重叠与默认操作ui" aria-label="Permalink to “UI 重叠与默认操作UI”">​</a></h3><ul><li>如果运行时出现两套 UI 重叠，常见原因不是地图 UI 出错，而是 <code>默认操作UI</code> 仍在自动生效。</li><li>官方给出的排查方向是： <ul><li>进入 <code>操作UI</code> 设置；</li><li>检查 <code>默认操作UI</code>；</li><li>关闭或改空默认项，避免和自定义 UI 叠加。</li></ul></li><li>这说明 <code>操作UI</code> 在运行时可能是自动出现的系统层界面，而不是只有手动切换才会出现。</li></ul><h3 id="互动按钮为什么不显示" tabindex="-1">互动按钮为什么不显示 <a class="header-anchor" href="#互动按钮为什么不显示" aria-label="Permalink to “互动按钮为什么不显示”">​</a></h3><ul><li><code>互动按钮</code> 默认不会一直显示在屏幕上。</li><li>它只有在角色接近或碰到 <code>可互动物体</code> 时才会出现。</li><li>如果想做常驻按钮，应该直接使用普通 <code>按钮</code> 组件，而不是互动按钮。</li><li>这说明互动按钮本质上是“上下文触发型 UI”。</li></ul><h3 id="角色走不动与碰撞盒" tabindex="-1">角色走不动与碰撞盒 <a class="header-anchor" href="#角色走不动与碰撞盒" aria-label="Permalink to “角色走不动与碰撞盒”">​</a></h3><ul><li>官方明确指出，大多数“角色走不动”问题都和 <code>碰撞阻挡</code> 有关。</li><li>排查时建议在试运行中打开 <code>查看碰撞盒</code>。</li><li>常见原因包括： <ul><li>地块自带 <code>阻挡通行</code></li><li>玩家碰撞盒过大</li><li>物体看起来能过，但碰撞盒实际上先撞上了</li></ul></li><li>这说明视觉外观和真实可通行区域并不总是一致，碰撞盒才是更真实的判定依据。</li></ul><h3 id="素材与地图物体的实例化关系" tabindex="-1">素材与地图物体的实例化关系 <a class="header-anchor" href="#素材与地图物体的实例化关系" aria-label="Permalink to “素材与地图物体的实例化关系”">​</a></h3><ul><li>地图中摆出来的是 <code>物体</code>，素材栏里的是 <code>素材模板</code>。</li><li>当素材拖进地图的那一刻，会被 <code>实例化</code> 成物体，并把当时属性做一次快照。</li><li>后续再修改素材栏内的模板，已经摆在地图中的旧物体通常不会自动变化。</li><li>如果想把地图中某个物体的修改反推回模板，可使用 <code>应用到原素材</code>。</li><li>这可以用“类与实例 / 模板与实例”的思路去理解。</li></ul><h3 id="对-ai-的可用标签-13" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-13" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>UI重叠</li><li>默认操作UI</li><li>互动按钮</li><li>可互动物体</li><li>角色走不动</li><li>碰撞盒</li><li>阻挡通行</li><li>实例化</li><li>素材模板</li><li>应用到原素材</li></ul><hr><h2 id="_16-实用功能补强-卡牌拖拽放置与坐标转换" tabindex="-1">16. 实用功能补强：卡牌拖拽放置与坐标转换 <a class="header-anchor" href="#_16-实用功能补强-卡牌拖拽放置与坐标转换" aria-label="Permalink to “16. 实用功能补强：卡牌拖拽放置与坐标转换”">​</a></h2><h3 id="主题-14" tabindex="-1">主题 <a class="header-anchor" href="#主题-14" aria-label="Permalink to “主题”">​</a></h3><p>卡牌拖拽放置的实现核心</p><h3 id="核心结论" tabindex="-1">核心结论 <a class="header-anchor" href="#核心结论" aria-label="Permalink to “核心结论”">​</a></h3><ul><li>官方明确指出：<code>卡牌拖拽放置</code> 这个功能，核心涉及 <code>地图和UI之间的坐标转换</code>。</li><li>这意味着它不是单纯的 UI 拖动问题，而是至少同时涉及： <ul><li>UI 坐标体系</li><li>地图坐标体系</li><li>两套坐标之间的换算</li></ul></li></ul><h3 id="对现有知识体系的连接" tabindex="-1">对现有知识体系的连接 <a class="header-anchor" href="#对现有知识体系的连接" aria-label="Permalink to “对现有知识体系的连接”">​</a></h3><ul><li>它与前面已经整理出的 <code>坐标与向量</code> 知识形成直接应用关系。</li><li>也说明官方“实用功能”栏目不是只给结果，而是在引导创作者把基础数学知识应用到实际玩法里。</li></ul><h3 id="当前可确认的应用理解" tabindex="-1">当前可确认的应用理解 <a class="header-anchor" href="#当前可确认的应用理解" aria-label="Permalink to “当前可确认的应用理解”">​</a></h3><ul><li>UI 中显示一张卡牌，并不等于地图中已经放下一个物体。</li><li>当玩家拖动并释放卡牌时，通常需要把 UI 位置换算成地图位置，才能真正完成“放置”。</li><li>因而这类玩法通常会关联： <ul><li>UI 跟手拖拽</li><li>坐标换算</li><li>地图中生成/放置物体</li></ul></li></ul><h3 id="对-ai-的可用标签-14" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-14" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>卡牌拖拽放置</li><li>UI坐标</li><li>地图坐标</li><li>坐标转换</li><li>放置玩法</li><li>实用功能</li></ul><hr><h2 id="_17-官方教程栏目结构补强" tabindex="-1">17. 官方教程栏目结构补强 <a class="header-anchor" href="#_17-官方教程栏目结构补强" aria-label="Permalink to “17. 官方教程栏目结构补强”">​</a></h2><h3 id="主题-15" tabindex="-1">主题 <a class="header-anchor" href="#主题-15" aria-label="Permalink to “主题”">​</a></h3><p>基础知识、常见问题、实用功能的栏目证据</p><h3 id="基础知识栏目" tabindex="-1">基础知识栏目 <a class="header-anchor" href="#基础知识栏目" aria-label="Permalink to “基础知识栏目”">​</a></h3><p>当前可稳定确认包含：</p><ul><li>什么是广播</li><li>什么是自定义组件</li><li>什么是素材</li><li>素材的基础操作</li><li>什么是组件</li><li>什么是属性</li><li>什么是指令</li><li>什么是UI</li><li>地图层级的调整和设置</li></ul><h3 id="常见问题栏目" tabindex="-1">常见问题栏目 <a class="header-anchor" href="#常见问题栏目" aria-label="Permalink to “常见问题栏目”">​</a></h3><p>当前可稳定确认包含：</p><ul><li>如何添加玩家</li><li>为什么表改了之后不生效</li><li>为什么切换UI时找不到做好的UI</li><li>为什么有两个重叠的UI还关不掉</li><li>为什么角色在地图上走不动</li><li>为什么UI-互动按钮不在屏幕中显示</li><li>为什么修改了素材属性地图中无变化</li><li>以及碰撞盒 / 阻挡通行 / 素材与物体区别等方向</li></ul><h3 id="实用功能栏目" tabindex="-1">实用功能栏目 <a class="header-anchor" href="#实用功能栏目" aria-label="Permalink to “实用功能栏目”">​</a></h3><p>当前可稳定确认包含：</p><ul><li>计算玩家未登录天数</li><li>怎么做玩家首次登录</li><li>卡牌拖拽放置</li></ul><h3 id="结构意义" tabindex="-1">结构意义 <a class="header-anchor" href="#结构意义" aria-label="Permalink to “结构意义”">​</a></h3><ul><li>官方教程体系已经明显分为： <ul><li>概念基础</li><li>常见踩坑答疑</li><li>具体功能实现</li></ul></li><li>这对后续整理知识库非常重要，因为可以按“定义 / 问题 / 方案”三层结构组织。</li></ul><h3 id="对-ai-的可用标签-15" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-15" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>基础知识栏目</li><li>常见问题栏目</li><li>实用功能栏目</li><li>教程导航</li><li>知识树</li><li>官方目录</li></ul><hr><h2 id="_18-基础知识栏目细化" tabindex="-1">18. 基础知识栏目细化 <a class="header-anchor" href="#_18-基础知识栏目细化" aria-label="Permalink to “18. 基础知识栏目细化”">​</a></h2><h3 id="主题-16" tabindex="-1">主题 <a class="header-anchor" href="#主题-16" aria-label="Permalink to “主题”">​</a></h3><p>基础知识栏目下已确认的具体条目</p><h3 id="当前可稳定确认的条目" tabindex="-1">当前可稳定确认的条目 <a class="header-anchor" href="#当前可稳定确认的条目" aria-label="Permalink to “当前可稳定确认的条目”">​</a></h3><ul><li>什么是广播</li><li>什么是自定义组件</li><li>什么是素材</li><li>素材的基础操作</li><li>什么是组件</li><li>什么是属性</li><li>什么是指令</li><li>什么是 UI</li><li>地图层级的调整和设置</li></ul><h3 id="结构意义-1" tabindex="-1">结构意义 <a class="header-anchor" href="#结构意义-1" aria-label="Permalink to “结构意义”">​</a></h3><ul><li>这说明“基础知识”并不只是一个抽象栏目名，而是已经形成了从概念到编辑器操作的完整入门链。</li><li>大致可以分成三层： <ul><li>基础概念：广播、自定义组件、素材、组件、属性、指令、UI</li><li>基础操作：素材的基础操作</li><li>场景编辑：地图层级的调整和设置</li></ul></li><li>这对后续构建新手学习路径很有价值，可以按“先理解名词，再理解结构，再进入编辑器操作”的顺序组织内容。</li></ul><h3 id="对-ai-的可用标签-16" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-16" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>基础知识</li><li>入门教程</li><li>广播</li><li>自定义组件</li><li>素材</li><li>组件</li><li>属性</li><li>指令</li><li>UI</li><li>地图层级</li></ul><hr><h2 id="_19-录屏系统指令" tabindex="-1">19. 录屏系统指令 <a class="header-anchor" href="#_19-录屏系统指令" aria-label="Permalink to “19. 录屏系统指令”">​</a></h2><h3 id="主题-17" tabindex="-1">主题 <a class="header-anchor" href="#主题-17" aria-label="Permalink to “主题”">​</a></h3><p>开始录屏与结束录屏</p><h3 id="开始录屏" tabindex="-1">开始录屏 <a class="header-anchor" href="#开始录屏" aria-label="Permalink to “开始录屏”">​</a></h3><ul><li><code>开始录屏</code> 会调用玩家手机的系统录屏能力。</li><li>这不是单纯的游戏内标记，而是真正发起一次录屏请求。</li><li>从截图可稳定确认： <ul><li>会出现权限请求</li><li>由“游戏”发起录屏请求</li><li>玩家需要手动允许</li></ul></li><li>因此它适合做： <ul><li>高光时刻录制</li><li>通关视频录制</li><li>教学操作留档</li><li>玩家投稿素材采集</li></ul></li></ul><h3 id="结束录屏" tabindex="-1">结束录屏 <a class="header-anchor" href="#结束录屏" aria-label="Permalink to “结束录屏”">​</a></h3><ul><li><code>结束录屏</code> 用于终止当前正在进行的录屏。</li><li>它和 <code>开始录屏</code> 构成一组完整录屏控制能力。</li><li>当前更像纯动作型收尾指令，未见额外参数。</li></ul><h3 id="使用理解" tabindex="-1">使用理解 <a class="header-anchor" href="#使用理解" aria-label="Permalink to “使用理解”">​</a></h3><ul><li>录屏功能与设备权限强相关，不是所有场景都一定能无感成功。</li><li>如果玩家未授权，开始录屏可能无法正常工作。</li><li>这类能力很适合与： <ul><li>剧情演出</li><li>Boss 战</li><li>结算高光</li><li>一键分享前置录制 联动设计。</li></ul></li></ul><h3 id="对-ai-的可用标签-17" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-17" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>开始录屏</li><li>结束录屏</li><li>录屏权限</li><li>系统录屏</li><li>手机权限请求</li><li>高光录制</li></ul><hr><h2 id="_20-噪声页与低价值相邻页处理原则" tabindex="-1">20. 噪声页与低价值相邻页处理原则 <a class="header-anchor" href="#_20-噪声页与低价值相邻页处理原则" aria-label="Permalink to “20. 噪声页与低价值相邻页处理原则”">​</a></h2><h3 id="主题-18" tabindex="-1">主题 <a class="header-anchor" href="#主题-18" aria-label="Permalink to “主题”">​</a></h3><p>如何处理 OCR 中混入的评论区、界面噪声与非正文相邻页</p><h3 id="当前确认" tabindex="-1">当前确认 <a class="header-anchor" href="#当前确认" aria-label="Permalink to “当前确认”">​</a></h3><ul><li>并不是所有带编号截图都属于可稳定提炼的官方教程正文。</li><li>例如 <code>114528</code> 这一页，OCR 结果主体被评论区和界面噪声覆盖，只残留少量零散词： <ul><li>脚本语句</li><li>数字</li><li>余数</li></ul></li><li>这类页面不足以作为正式知识证据，但仍有留档价值。</li></ul><h3 id="建议归档规则" tabindex="-1">建议归档规则 <a class="header-anchor" href="#建议归档规则" aria-label="Permalink to “建议归档规则”">​</a></h3><ul><li>若页面主体是： <ul><li>评论区</li><li>用户昵称</li><li>弹幕/互动噪声</li><li>无法还原的界面残片 则应标记为：</li><li><code>噪声页</code></li><li>或 <code>非稳定教程正文</code></li></ul></li><li>这类页可以： <ul><li>在 OCR 索引中保留编号占位；</li><li>在知识索引中只记录处理原则；</li><li>不把其内容当作正式教程知识点引用。</li></ul></li></ul><h3 id="这样做的意义" tabindex="-1">这样做的意义 <a class="header-anchor" href="#这样做的意义" aria-label="Permalink to “这样做的意义”">​</a></h3><ul><li>避免把评论区内容误当成官方规则。</li><li>避免后续重复扫描同一张低价值页面。</li><li>让知识库中的“正式证据”和“占位留档”分层更清楚。</li></ul><h3 id="对-ai-的可用标签-18" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-18" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>噪声页</li><li>评论区</li><li>OCR 误入</li><li>非正文</li><li>归档规则</li><li>低价值页</li></ul><hr><h2 id="_21-地图、货币与战斗基础组件补充" tabindex="-1">21. 地图、货币与战斗基础组件补充 <a class="header-anchor" href="#_21-地图、货币与战斗基础组件补充" aria-label="Permalink to “21. 地图、货币与战斗基础组件补充”">​</a></h2><h3 id="主题-19" tabindex="-1">主题 <a class="header-anchor" href="#主题-19" aria-label="Permalink to “主题”">​</a></h3><p>地图组件、货币系统、近战武器、角色组件</p><h3 id="地图组件与联机设置迁移" tabindex="-1">地图组件与联机设置迁移 <a class="header-anchor" href="#地图组件与联机设置迁移" aria-label="Permalink to “地图组件与联机设置迁移”">​</a></h3><ul><li>地图组件当前可确认包含较完整的摄像机参数： <ul><li>初始聚焦坐标</li><li>可拖动轴（XY / 仅X / 仅Y）</li><li>缩放最小值 / 最大值</li></ul></li><li>官方还明确说明：旧版曾存在 <code>联机设置组件</code>，但后来被取消。</li><li>被取消后，相关能力改为主要通过脚本或其他系统入口控制，因为联机设置更适合全局级，而不是地图级。</li><li>当前仍能确认的联机相关内容包括： <ul><li>玩家名可见度</li><li>聊天可见度</li><li>局内排行榜</li></ul></li><li>可见度至少支持： <ul><li>所有人可见</li><li>同阵营可见</li><li>隐藏</li></ul></li><li><code>局内排行榜</code> 的开关后来放到了 <code>地图UI设置</code> 内，但排行榜数据仍需要手动上传。</li></ul><h3 id="货币组件" tabindex="-1">货币组件 <a class="header-anchor" href="#货币组件" aria-label="Permalink to “货币组件”">​</a></h3><ul><li>创游内置了一整套货币系统，目标是让创作者低门槛制作交易功能。</li><li>新建路径可确认是：<code>道具 -&gt; 画一个 -&gt; 货币</code>。</li><li><code>货币组件</code> 属于默认组件，不能后期随便给普通素材补挂。</li><li>货币组件本身没有简单属性页，说明它更像一种带内置规则的特殊素材类型。</li></ul><h3 id="货币条组件" tabindex="-1">货币条组件 <a class="header-anchor" href="#货币条组件" aria-label="Permalink to “货币条组件”">​</a></h3><ul><li><code>货币条组件</code> 也是默认组件，只挂载在官方内置 <code>货币条</code> 素材上。</li><li>创建路径可确认是：<code>画一个 -&gt; 货币条</code>。</li><li>货币条至少包含： <ul><li>名称</li><li>贴图</li><li>子物体</li><li>九宫切图</li><li>对齐父物体</li><li>货币</li></ul></li><li>该素材默认自带两个子物体： <ul><li>货币贴图</li><li>数量文本</li></ul></li><li>这说明货币条不只是逻辑对象，而是已经自带显示结构的复合 UI 素材。</li></ul><h3 id="近战武器组件" tabindex="-1">近战武器组件 <a class="header-anchor" href="#近战武器组件" aria-label="Permalink to “近战武器组件”">​</a></h3><ul><li><code>近战武器组件</code> 可以直接产生伤害，这是它与远程武器的重要区别。</li><li>当前可确认的基础属性包括： <ul><li>持握方式</li><li>攻击方式</li><li>伤害值</li></ul></li><li>结合相邻补证页，还能确认近战系统还存在更完整的战斗参数组，如暴击、击退、攻击频率、特殊效果与攻击事件链。</li></ul><h3 id="角色组件" tabindex="-1">角色组件 <a class="header-anchor" href="#角色组件" aria-label="Permalink to “角色组件”">​</a></h3><ul><li>只有挂载了 <code>角色组件</code>，物体才可以被当作主角。</li><li><code>角色组件</code> 依赖 <code>物理组件</code>。</li><li>当前可确认的关键属性包括： <ul><li>移动方式</li><li>动画</li><li>角色朝向</li><li>移动速度</li><li>起步加速度</li><li>减速度</li><li>跳跃高度</li><li>跳跃段数</li><li>爬墙跳</li></ul></li><li>官方特别强调： <ul><li>主角必须选 <code>玩家控制</code></li><li>NPC / 怪物则按设定的移动方式运行</li></ul></li><li>还能确认一个默认朝向规则：创游角色正方向默认朝右，因此即使角色游戏中主要朝左出现，绘制时通常也应按朝右的基准来做。</li></ul><h3 id="对-ai-的可用标签-19" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-19" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>地图组件</li><li>联机设置</li><li>货币组件</li><li>货币条组件</li><li>近战武器组件</li><li>角色组件</li><li>摄像机参数</li><li>玩家名可见度</li><li>聊天可见度</li><li>局内排行榜</li></ul><hr><h2 id="_22-ui-输入组件与背包系统补充" tabindex="-1">22. UI 输入组件与背包系统补充 <a class="header-anchor" href="#_22-ui-输入组件与背包系统补充" aria-label="Permalink to “22. UI 输入组件与背包系统补充”">​</a></h2><h3 id="主题-20" tabindex="-1">主题 <a class="header-anchor" href="#主题-20" aria-label="Permalink to “主题”">​</a></h3><p>背包、移动摇杆、技能摇杆、互动按钮、摇杆、输入框</p><h3 id="背包组件" tabindex="-1">背包组件 <a class="header-anchor" href="#背包组件" aria-label="Permalink to “背包组件”">​</a></h3><ul><li><code>背包组件</code> 是默认组件，只挂载在官方 UI 素材 <code>背包</code> 上。</li><li>面板可见的 <code>宽 / 高</code> 主要影响显示布局，不直接代表真正容量。</li><li>真正决定格子数量的是仅脚本可见的 <code>背包容量</code>，最大为 <code>200</code>。</li><li>还能确认的脚本属性包括： <ul><li>是否自动整理</li><li>某道具的数量</li></ul></li><li>指令至少包括： <ul><li>整理背包</li><li>卸下武器</li><li>获得道具</li><li>清空背包</li><li>打开背包</li></ul></li><li>这说明背包组件同时包含显示、容量、整理逻辑和道具管理能力。</li></ul><h3 id="移动摇杆" tabindex="-1">移动摇杆 <a class="header-anchor" href="#移动摇杆" aria-label="Permalink to “移动摇杆”">​</a></h3><ul><li><code>移动摇杆</code> 是默认组件，只挂载在官方内置资源 <code>移动摇杆</code> 上。</li><li>也支持在 <code>操作UI -&gt; 画一个 -&gt; 移动摇杆</code> 中自定义样式。</li><li>当前可确认有两种类型： <ul><li>动态</li><li>静态</li></ul></li><li>关键事件包括： <ul><li>当按下时</li><li>当角度变化时</li><li>当抬起时</li></ul></li><li>它更偏向“控制当前玩家移动”的专用输入控件。</li></ul><h3 id="技能摇杆" tabindex="-1">技能摇杆 <a class="header-anchor" href="#技能摇杆" aria-label="Permalink to “技能摇杆”">​</a></h3><ul><li><code>技能摇杆</code> 是默认组件，绑定在官方内置资源 <code>技能摇杆</code> 上，也支持自定义样式。</li><li>关键属性/事件包括： <ul><li>技能位</li><li>当按下时</li><li>当摇柄移动时</li><li>当抬起时</li></ul></li><li><code>当摇柄移动时</code> 会给出： <ul><li>角度</li><li>向量</li></ul></li><li>这意味着它非常适合做技能施法方向与力度判断。</li><li>还可确认一个重要前提：主角对应技能位上必须真的有技能，否则技能摇杆不会正常显示或工作。</li></ul><h3 id="互动按钮" tabindex="-1">互动按钮 <a class="header-anchor" href="#互动按钮" aria-label="Permalink to “互动按钮”">​</a></h3><ul><li><code>互动按钮</code> 是默认组件，只挂载在官方内置资源 <code>互动按钮</code> 上。</li><li>支持的关键属性/事件包括： <ul><li>点击效果</li><li>防连点</li><li>当点击时</li></ul></li><li>互动按钮默认在运行时隐藏，只有主角碰到 <code>可互动物体</code> 时才会显示。</li><li>这说明它本质上是“上下文触发型交互按钮”。</li></ul><h3 id="通用摇杆" tabindex="-1">通用摇杆 <a class="header-anchor" href="#通用摇杆" aria-label="Permalink to “通用摇杆”">​</a></h3><ul><li><code>摇杆组件</code> 与移动摇杆不同，更适合做自定义控制对象。</li><li>它不仅可用于 <code>操作UI</code>，也可用于 <code>地图UI</code>。</li><li>同样支持： <ul><li>动态</li><li>静态</li></ul></li><li>它的按下 / 移动 / 抬起事件都会提供： <ul><li>角度</li><li>向量</li></ul></li><li>因而很适合拿来做炮台、载具、机关、瞄准等自定义控制。</li></ul><h3 id="输入框组件" tabindex="-1">输入框组件 <a class="header-anchor" href="#输入框组件" aria-label="Permalink to “输入框组件”">​</a></h3><ul><li><code>输入框组件</code> 用于接收玩家输入，是默认组件，只挂载在官方 UI 素材 <code>输入框</code> 上。</li><li>可存在于 <code>操作UI</code> 或 <code>地图UI</code>。</li><li>关键属性/事件包括： <ul><li>文字</li><li>输入提示</li><li>长度限制</li><li>当输入完成时</li></ul></li><li><code>当输入完成时</code> 会回传参数 <code>文字</code>，也就是玩家实际输入的内容。</li><li>触发时机与手机输入法行为有关，可能是关闭键盘，也可能是按回车。</li></ul><h3 id="对-ai-的可用标签-20" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-20" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>背包组件</li><li>背包容量</li><li>自动整理</li><li>移动摇杆</li><li>技能摇杆</li><li>互动按钮</li><li>摇杆组件</li><li>输入框组件</li><li>角度</li><li>向量</li><li>玩家输入</li></ul><hr><h2 id="_23-表现与设备能力指令补充" tabindex="-1">23. 表现与设备能力指令补充 <a class="header-anchor" href="#_23-表现与设备能力指令补充" aria-label="Permalink to “23. 表现与设备能力指令补充”">​</a></h2><h3 id="主题-21" tabindex="-1">主题 <a class="header-anchor" href="#主题-21" aria-label="Permalink to “主题”">​</a></h3><p>弹簧、屏幕震动、设置音量、播放音效、播放BGM、停止BGM、手机振动、复制到剪切板</p><h3 id="弹簧组件" tabindex="-1">弹簧组件 <a class="header-anchor" href="#弹簧组件" aria-label="Permalink to “弹簧组件”">​</a></h3><ul><li><code>弹簧组件</code> 只能挂载在装置素材上。</li><li>它的核心作用是让角色踩上后被弹飞，表现类似蹦床。</li><li>官方特别强调它通常要和 <code>碰撞阻挡</code> 组件共同使用，尤其是设置上部阻挡，避免角色掉下去。</li><li>当前可确认的关键项包括： <ul><li>弹跳高度</li><li>当弹起时</li><li>阻挡通行</li></ul></li><li><code>当弹起时</code> 会把 <code>弹起者</code> 作为参数传入。</li></ul><h3 id="屏幕震动" tabindex="-1">屏幕震动 <a class="header-anchor" href="#屏幕震动" aria-label="Permalink to “屏幕震动”">​</a></h3><ul><li><code>屏幕震动</code> 用于让游戏画面产生镜头摇晃效果。</li><li>参数至少包括： <ul><li>横向幅度</li><li>纵向幅度</li><li>震动频率</li><li>持续时间</li></ul></li><li>非常适合受击反馈、爆炸、Boss 出场和地震演出。</li></ul><h3 id="设置音量" tabindex="-1">设置音量 <a class="header-anchor" href="#设置音量" aria-label="Permalink to “设置音量”">​</a></h3><ul><li><code>设置音量</code> 只有一个核心参数，范围是 <code>0~100</code>。</li><li>它影响的是整个游戏内声音大小，而不是单独某一路。</li><li>官方明确指出它会同时影响： <ul><li>BGM</li><li>音效</li></ul></li></ul><h3 id="播放音效" tabindex="-1">播放音效 <a class="header-anchor" href="#播放音效" aria-label="Permalink to “播放音效”">​</a></h3><ul><li><code>播放音效</code> 用于播放指定音效。</li><li>官方明确区分了音效与 BGM： <ul><li>音效短、可同时多个</li><li>BGM 长、同时只允许一个</li></ul></li><li>当前可确认的能力边界： <ul><li>音效支持 10 秒以内</li><li>可同时播放 30 个音效</li></ul></li><li>参数至少包括： <ul><li>音效</li><li>音量</li><li>启用距离衰减</li></ul></li><li>距离衰减非常适合做空间感声音表现。</li></ul><h3 id="播放-停止-bgm" tabindex="-1">播放 / 停止 BGM <a class="header-anchor" href="#播放-停止-bgm" aria-label="Permalink to “播放 / 停止 BGM”">​</a></h3><ul><li><code>播放BGM</code> 用于选择并播放背景音乐。</li><li>因为系统同时只能存在 1 首 BGM，所以新播放会停止旧 BGM。</li><li>参数至少包括： <ul><li>BGM</li><li>播放次数（循环 / 一次）</li><li>音量</li></ul></li><li><code>停止BGM</code> 用于关闭当前 BGM。</li><li>官方还明确说明：当前没有暂停播放 BGM 的功能。</li></ul><h3 id="手机振动" tabindex="-1">手机振动 <a class="header-anchor" href="#手机振动" aria-label="Permalink to “手机振动”">​</a></h3><ul><li><code>手机振动</code> 会直接调用设备振动反馈。</li><li>当前可确认的振动模式至少包括： <ul><li>短振</li><li>长振</li></ul></li><li>适合做点击、受击、警报等基础触觉反馈，但细腻程度不如手柄震动。</li></ul><h3 id="复制到剪切板" tabindex="-1">复制到剪切板 <a class="header-anchor" href="#复制到剪切板" aria-label="Permalink to “复制到剪切板”">​</a></h3><ul><li><code>复制到剪切板</code> 会把一段文字写入玩家手机剪切板。</li><li>参数不必是固定文本，也可以是变量、拼接结果、动态字符串。</li><li>适合做： <ul><li>复制兑换码</li><li>复制房间号</li><li>复制提示文本</li><li>复制联机信息</li></ul></li></ul><h3 id="对-ai-的可用标签-21" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-21" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>弹簧组件</li><li>屏幕震动</li><li>设置音量</li><li>播放音效</li><li>播放BGM</li><li>停止BGM</li><li>手机振动</li><li>复制到剪切板</li><li>镜头表现</li><li>设备能力</li></ul><hr><h2 id="_24-配置表属性与指令补强" tabindex="-1">24. 配置表属性与指令补强 <a class="header-anchor" href="#_24-配置表属性与指令补强" aria-label="Permalink to “24. 配置表属性与指令补强”">​</a></h2><h3 id="主题-22" tabindex="-1">主题 <a class="header-anchor" href="#主题-22" aria-label="Permalink to “主题”">​</a></h3><p>配置表的读取、判断、增删行与报错边界</p><h3 id="配置表属性" tabindex="-1">配置表属性 <a class="header-anchor" href="#配置表属性" aria-label="Permalink to “配置表属性”">​</a></h3><p>当前可稳定确认的配置表属性包括：</p><ul><li><code>总行数</code></li><li><code>第n行</code></li><li><code>名为xx的行</code></li><li><code>是否存在某行</code></li></ul><h4 id="总行数" tabindex="-1">总行数 <a class="header-anchor" href="#总行数" aria-label="Permalink to “总行数”">​</a></h4><ul><li>返回一个数字类型的值，表示当前配置表内的总行数。</li><li>适合做： <ul><li>遍历前取上限</li><li>表是否为空判断</li><li>动态统计行数</li></ul></li></ul><h4 id="第n行" tabindex="-1">第n行 <a class="header-anchor" href="#第n行" aria-label="Permalink to “第n行”">​</a></h4><ul><li>返回表中的第 n 行数据。</li><li>读取到这一行后，还可以继续取该行中的具体属性。</li><li>重要边界： <ul><li>如果没有第 n 行，会直接报错。</li></ul></li></ul><h4 id="名为xx的行" tabindex="-1">名为xx的行 <a class="header-anchor" href="#名为xx的行" aria-label="Permalink to “名为xx的行”">​</a></h4><ul><li>按行名检索并返回对应行。</li><li>同样可以继续读取该行中的具体字段。</li><li>重要边界： <ul><li>如果找不到该行，也会直接报错。</li></ul></li></ul><h4 id="是否存在某行" tabindex="-1">是否存在某行 <a class="header-anchor" href="#是否存在某行" aria-label="Permalink to “是否存在某行”">​</a></h4><ul><li>返回一个真假值。</li><li>用于在正式读取前，先判断某一行是否存在。</li><li>这是避免脚本直接报错的关键保护手段。</li></ul><h3 id="配置表指令" tabindex="-1">配置表指令 <a class="header-anchor" href="#配置表指令" aria-label="Permalink to “配置表指令”">​</a></h3><p>当前可稳定确认的配置表指令包括：</p><ul><li><code>从表中移除第n行</code></li><li><code>从表中移除名为xx的行</code></li><li><code>添加一行</code></li></ul><h4 id="移除第n行" tabindex="-1">移除第n行 <a class="header-anchor" href="#移除第n行" aria-label="Permalink to “移除第n行”">​</a></h4><ul><li>按行号删除指定行。</li><li>适合已知行号、顺序处理型的表操作。</li></ul><h4 id="移除名为xx的行" tabindex="-1">移除名为xx的行 <a class="header-anchor" href="#移除名为xx的行" aria-label="Permalink to “移除名为xx的行”">​</a></h4><ul><li>按行名删除指定行。</li><li>适合配置项有稳定主键名、需要精确删除某一项时使用。</li></ul><h4 id="添加一行" tabindex="-1">添加一行 <a class="header-anchor" href="#添加一行" aria-label="Permalink to “添加一行”">​</a></h4><ul><li>可以在配置表中新增一行。</li><li>更关键的是，在 <code>设置 / 新建</code> 语境下，它还能把“新添加的这一行”作为返回值交给变量。</li><li>这意味着可以立刻继续： <ul><li>给新行写属性</li><li>构造新记录</li><li>做运行时临时配置生成</li></ul></li></ul><h3 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to “使用建议”">​</a></h3><ul><li>如果脚本里需要按行读取，优先写成： <ul><li>先 <code>是否存在某行</code></li><li>再 <code>读取该行</code></li></ul></li><li>因为： <ul><li>读不存在的第 n 行会报错</li><li>读不存在的命名行也会报错</li></ul></li><li>这让配置表的安全访问模式变得很明确： <ul><li>先判断</li><li>再读取</li><li>再修改/删除</li></ul></li></ul><h3 id="与前文的关系" tabindex="-1">与前文的关系 <a class="header-anchor" href="#与前文的关系" aria-label="Permalink to “与前文的关系”">​</a></h3><ul><li>这部分和前面“配置表 vs 变量表”的知识正好衔接： <ul><li><code>配置表</code> 更偏静态规则数据</li><li>但创游依然给了运行时增删行能力</li></ul></li><li>因此它既能用于： <ul><li>纯策划配表读取</li><li>也能用于运行期临时构造表数据</li></ul></li></ul><h3 id="对-ai-的可用标签-22" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-22" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>配置表</li><li>总行数</li><li>第n行</li><li>名为xx的行</li><li>是否存在某行</li><li>添加一行</li><li>移除第n行</li><li>移除名为xx的行</li><li>表报错边界</li><li>安全读取</li></ul><hr><h2 id="_26-聊天交互组件补充" tabindex="-1">26. 聊天交互组件补充 <a class="header-anchor" href="#_26-聊天交互组件补充" aria-label="Permalink to “26. 聊天交互组件补充”">​</a></h2><h3 id="主题-23" tabindex="-1">主题 <a class="header-anchor" href="#主题-23" aria-label="Permalink to “主题”">​</a></h3><p>快捷聊天按钮与聊天输入入口</p><h3 id="快捷聊天按钮" tabindex="-1">快捷聊天按钮 <a class="header-anchor" href="#快捷聊天按钮" aria-label="Permalink to “快捷聊天按钮”">​</a></h3><ul><li><code>快捷聊天按钮</code> 是默认组件，只挂载在官方内置资源 <code>快捷聊天按钮</code> 上。</li><li>点击该按钮后，会弹出输入框，方便玩家在游戏内进行交流。</li><li>当前可稳定确认的简单属性包括： <ul><li><code>点击效果</code></li></ul></li><li><code>点击效果</code> 至少支持： <ul><li><code>放大</code></li><li><code>无</code></li></ul></li></ul><h3 id="与其他-ui-输入组件的区别" tabindex="-1">与其他 UI 输入组件的区别 <a class="header-anchor" href="#与其他-ui-输入组件的区别" aria-label="Permalink to “与其他 UI 输入组件的区别”">​</a></h3><ul><li>它和 <code>普通按钮</code> 不同： <ul><li>普通按钮更偏通用点击触发逻辑；</li><li>快捷聊天按钮则自带“进入聊天输入”的用途。</li></ul></li><li>它和 <code>输入框</code> 也不同： <ul><li>输入框是直接接收玩家文字输入的通用组件；</li><li>快捷聊天按钮更像一个聊天入口，会先通过按钮交互再进入输入流程。</li></ul></li></ul><h3 id="使用理解-1" tabindex="-1">使用理解 <a class="header-anchor" href="#使用理解-1" aria-label="Permalink to “使用理解”">​</a></h3><ul><li>这说明官方 UI 组件里不仅有“控制角色”的摇杆类，也有面向“玩家交流”的聊天入口组件。</li><li>它适合归入： <ul><li>操作 UI</li><li>聊天功能入口</li><li>社交交互组件</li></ul></li></ul><h3 id="对-ai-的可用标签-23" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-23" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>快捷聊天按钮</li><li>聊天入口</li><li>输入框</li><li>点击效果</li><li>放大</li><li>UI 交互</li><li>玩家交流</li></ul><hr><h2 id="_27-战斗、道具与生命系统补充" tabindex="-1">27. 战斗、道具与生命系统补充 <a class="header-anchor" href="#_27-战斗、道具与生命系统补充" aria-label="Permalink to “27. 战斗、道具与生命系统补充”">​</a></h2><h3 id="主题-24" tabindex="-1">主题 <a class="header-anchor" href="#主题-24" aria-label="Permalink to “主题”">​</a></h3><p>道具组件、子弹组件、粒子特效组件、生命组件、武器槽组件</p><h3 id="道具组件" tabindex="-1">道具组件 <a class="header-anchor" href="#道具组件" aria-label="Permalink to “道具组件”">​</a></h3><ul><li><code>道具组件</code> 只能挂载在道具素材上。</li><li>当前可确认的基础结构包括： <ul><li>名称</li><li>物体描述</li><li>贴图</li><li>形状</li><li>道具主体设置</li><li>捡起后立刻使用</li><li>一次性道具</li><li>当使用时</li></ul></li><li>关键行为规则： <ul><li><code>捡起后立刻使用</code> 为真时，拾取后会立刻触发使用。</li><li><code>一次性道具</code> 为真时，每次使用会消耗一个，适合血瓶、经验球等消耗品。</li><li><code>一次性道具</code> 为假时，可重复多次使用，更适合功能型道具。</li><li><code>当使用时</code> 是事件类型，会在真正使用该道具的那一刻触发。</li></ul></li><li>版本迁移线索： <ul><li>3.x 引擎中道具组件的一些内容，在 4.x 中被调整到 <code>拾取参数</code> 一类位置。</li></ul></li></ul><h3 id="子弹组件" tabindex="-1">子弹组件 <a class="header-anchor" href="#子弹组件" aria-label="Permalink to “子弹组件”">​</a></h3><ul><li><code>子弹组件</code> 一般不会单独作为玩法主体出现，而是通常作为 <code>远程武器</code> 的子弹属性存在。</li><li>官方明确指出： <ul><li>远程武器本体通常不直接挂 <code>伤害组件</code>；</li><li>实际造成伤害的常常是子弹。</li></ul></li><li>当前可确认的核心属性包括： <ul><li>重力倍数</li><li>子弹推进加速度</li><li>子弹特效</li><li>反弹次数</li><li>穿透个数</li></ul></li><li>这说明远程武器系统的伤害、弹道和表现逻辑高度依赖子弹组件。</li></ul><h3 id="粒子特效组件" tabindex="-1">粒子特效组件 <a class="header-anchor" href="#粒子特效组件" aria-label="Permalink to “粒子特效组件”">​</a></h3><ul><li>当前截图能稳定确认标题 <code>粒子特效组件</code> 存在。</li><li>虽然正文 OCR 仍较少，但这已足以证明官方教程中存在专门的粒子特效组件条目。</li><li>当前更适合作为“专题存在证据”，等待相邻页进一步补足其属性与结构说明。</li></ul><h3 id="生命组件" tabindex="-1">生命组件 <a class="header-anchor" href="#生命组件" aria-label="Permalink to “生命组件”">​</a></h3><ul><li>除 <code>道具</code> 和 <code>装饰</code> 外，其余地图素材基本都可以挂载 <code>生命组件</code>。</li><li>挂载生命组件后，物体就能受到 <code>伤害</code> 或 <code>近战武器</code> 的攻击。</li><li>当前可确认的核心属性/事件包括： <ul><li>血量</li><li>被击退比例</li><li>受击后无敌</li><li>血条显示时机</li><li>受击显示飘字</li><li>当受击时</li><li>当死亡时</li></ul></li><li>官方特别强调： <ul><li>当血量降为 0 时，会触发 <code>当死亡时</code>；</li><li>但角色不会一定自动销毁；</li><li>若需要真正从地图中消失，通常还要在脚本中执行 <code>销毁自身</code>。</li></ul></li><li>这说明“死亡”在创游中更像一个脚本事件，而不是完全硬编码的自动清理流程。</li></ul><h3 id="武器槽组件" tabindex="-1">武器槽组件 <a class="header-anchor" href="#武器槽组件" aria-label="Permalink to “武器槽组件”">​</a></h3><ul><li>无论是近战武器还是远程武器，都依赖 <code>武器槽组件</code> 才能被角色或装置装备使用。</li><li><code>武器槽组件</code> 只能挂载在： <ul><li>角色素材</li><li>装置素材</li></ul></li><li>当前可确认的关键能力包括： <ul><li>当前武器</li><li>自动瞄准</li><li>锁敌半径</li><li>当武器打到目标时</li><li>当武器杀死目标时</li><li>当武器改变时</li></ul></li><li>这说明武器槽不仅负责“装上武器”，还承担： <ul><li>锁敌</li><li>命中回调</li><li>击杀回调</li><li>切换武器事件</li></ul></li><li>一个实用细节： <ul><li>角色与武器之间的位置关系，通常需要把角色实际摆进地图后再调整；</li><li>武器锚点相对角色的位置是统一基准。</li></ul></li></ul><h3 id="对-ai-的可用标签-24" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-24" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>道具组件</li><li>子弹组件</li><li>粒子特效组件</li><li>生命组件</li><li>武器槽组件</li><li>远程武器</li><li>伤害系统</li><li>当死亡时</li><li>自动瞄准</li><li>锁敌半径</li></ul><hr><h2 id="_28-商业化、商店与排行榜系统补充" tabindex="-1">28. 商业化、商店与排行榜系统补充 <a class="header-anchor" href="#_28-商业化、商店与排行榜系统补充" aria-label="Permalink to “28. 商业化、商店与排行榜系统补充”">​</a></h2><h3 id="主题-25" tabindex="-1">主题 <a class="header-anchor" href="#主题-25" aria-label="Permalink to “主题”">​</a></h3><p>分享游戏、观看视频广告、支付G币、输入兑换码、商店、排行榜、上传分数</p><h3 id="分享游戏" tabindex="-1">分享游戏 <a class="header-anchor" href="#分享游戏" aria-label="Permalink to “分享游戏”">​</a></h3><ul><li><code>分享游戏</code> 会打开分享面板，引导玩家把游戏分享到社交平台。</li><li>当前可确认的参数包括： <ul><li>分享文案</li><li>分享图</li><li>分享成功时</li><li>分享失败时</li></ul></li><li>这意味着分享系统不仅是传播入口，也可和奖励逻辑绑定。</li></ul><h3 id="观看视频广告" tabindex="-1">观看视频广告 <a class="header-anchor" href="#观看视频广告" aria-label="Permalink to “观看视频广告”">​</a></h3><ul><li><code>观看视频广告</code> 用于给玩家播放激励视频广告。</li><li>当前可确认的参数包括： <ul><li>展示图片</li><li>奖励说明</li><li>广告成功时</li><li>广告失败时</li></ul></li><li>官方还给出了平台层收益信息： <ul><li>玩家每成功完整观看一次广告；</li><li>创作者会获得 <code>100 G币（1金豆）</code> 的广告费。</li></ul></li><li>这说明该功能兼具： <ul><li>玩家激励入口</li><li>创作者变现入口</li></ul></li></ul><h3 id="支付g币" tabindex="-1">支付G币 <a class="header-anchor" href="#支付g币" aria-label="Permalink to “支付G币”">​</a></h3><ul><li><code>支付G币</code> 会打开 G 币支付面板，让玩家完成付费。</li><li>当前可确认的参数包括： <ul><li>金额</li><li>支付成功时</li><li>支付失败时</li></ul></li><li>还可确认两个实用细节： <ul><li>支付面板会给玩家约 <code>3 秒确认时间</code>；</li><li>调试模式下不会真的扣除 G 币。</li></ul></li></ul><h3 id="输入兑换码" tabindex="-1">输入兑换码 <a class="header-anchor" href="#输入兑换码" aria-label="Permalink to “输入兑换码”">​</a></h3><ul><li>官方内置的 <code>输入兑换码</code> 更适合做 <code>限量兑换码</code> 场景。</li><li>当前可确认的参数包括： <ul><li>兑换码表</li><li>验证成功时</li><li>验证失败时</li></ul></li><li>官方还明确提示： <ul><li>如果想做所有人都能用的常规兑换码；</li><li>更适合用脚本自行实现。</li></ul></li><li>这说明内置兑换码偏官方活动式、限量式方案，而不是万能码系统。</li></ul><h3 id="商店系统" tabindex="-1">商店系统 <a class="header-anchor" href="#商店系统" aria-label="Permalink to “商店系统”">​</a></h3><ul><li><code>打开商店</code> 指令用于打开一个已经创建好的商店。</li><li>商店至少包含： <ul><li>商店名</li><li>商品列表</li></ul></li><li>商品项当前可确认可设置： <ul><li>选择商品</li><li>库存数量</li><li>回收价</li></ul></li><li>这说明商店不仅支持买入，也支持一定程度上的卖出回收逻辑。</li></ul><h3 id="排行榜系统" tabindex="-1">排行榜系统 <a class="header-anchor" href="#排行榜系统" aria-label="Permalink to “排行榜系统”">​</a></h3><ul><li><code>打开排行榜</code> 指令用于打开一个已创建好的排行榜界面。</li><li>排行榜当前可确认至少有五个属性： <ul><li>名字</li><li>周期</li><li>排序</li><li>分数后缀</li><li>分数图标</li></ul></li><li>周期支持： <ul><li>日榜</li><li>周榜</li><li>月榜</li><li>永久排行榜</li></ul></li><li>横屏与竖屏下，排行榜界面表现可能不同。</li></ul><h3 id="上传分数" tabindex="-1">上传分数 <a class="header-anchor" href="#上传分数" aria-label="Permalink to “上传分数”">​</a></h3><ul><li><code>上传分数</code> 用于把数据提交到排行榜。</li><li>在普通指令面板中，分数来源通常受限于： <ul><li>计时器</li><li>某种道具数量</li></ul></li><li>但在脚本中更自由，只要是数字型变量即可上传。</li><li>上传方式当前可确认包括： <ul><li>保留最佳成绩</li><li>强制覆盖</li></ul></li></ul><h3 id="对-ai-的可用标签-25" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-25" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>分享游戏</li><li>激励广告</li><li>支付G币</li><li>输入兑换码</li><li>商店</li><li>排行榜</li><li>上传分数</li><li>变现</li><li>活动系统</li><li>经济系统</li></ul><hr><h2 id="_29-数字、真假值、文本、数组与配置表知识树补充" tabindex="-1">29. 数字、真假值、文本、数组与配置表知识树补充 <a class="header-anchor" href="#_29-数字、真假值、文本、数组与配置表知识树补充" aria-label="Permalink to “29. 数字、真假值、文本、数组与配置表知识树补充”">​</a></h2><h3 id="主题-26" tabindex="-1">主题 <a class="header-anchor" href="#主题-26" aria-label="Permalink to “主题”">​</a></h3><p>数字篇、真假值篇、文字篇、数组篇、表篇的结构化知识树</p><h3 id="数字篇" tabindex="-1">数字篇 <a class="header-anchor" href="#数字篇" aria-label="Permalink to “数字篇”">​</a></h3><p>当前可稳定确认数字专题至少包含：</p><ul><li>数字类型</li><li>数字运算符</li><li>取余数</li><li>三角函数</li><li>数字指令</li><li>随机数</li></ul><h4 id="数字类型" tabindex="-1">数字类型 <a class="header-anchor" href="#数字类型" aria-label="Permalink to “数字类型”">​</a></h4><ul><li>数字可以是整数，也可以是小数。</li><li><code>数字类型</code> 与 <code>文本里看起来像数字的内容</code> 不同： <ul><li>数字类型可直接参与运算；</li><li>文本中的数字字符不能直接参与数字运算。</li></ul></li><li>文本转数字失败时会得到 <code>NaN</code>。</li></ul><h4 id="数字运算符" tabindex="-1">数字运算符 <a class="header-anchor" href="#数字运算符" aria-label="Permalink to “数字运算符”">​</a></h4><ul><li>当前可确认包括： <ul><li>加法</li><li>减法</li><li>乘法 <code>*</code></li><li>除法 <code>/</code></li></ul></li><li>运算顺序强调：<code>先内块，后外块</code>。</li><li>除数不能为 0。</li></ul><h4 id="取余数" tabindex="-1">取余数 <a class="header-anchor" href="#取余数" aria-label="Permalink to “取余数”">​</a></h4><ul><li>用于返回除法后的余数。</li><li>当余数为 0 时表示整除。</li><li>创游中负数取余的符号与被除数一致。</li><li>小数取余可能出现浮点精度误差。</li></ul><h4 id="三角函数" tabindex="-1">三角函数 <a class="header-anchor" href="#三角函数" aria-label="Permalink to “三角函数”">​</a></h4><ul><li>当前可确认创游提供 6 个三角函数： <ul><li>sine</li><li>cose</li><li>tane</li><li>asine</li><li>acose</li><li>atane</li></ul></li><li>适合物理模拟、旋转、方向计算、极坐标转换。</li></ul><h4 id="数字指令" tabindex="-1">数字指令 <a class="header-anchor" href="#数字指令" aria-label="Permalink to “数字指令”">​</a></h4><ul><li>当前可确认包括： <ul><li>四舍五入</li><li>向上取整</li><li>向下取整</li><li>绝对值</li><li>相反数</li><li>n次方</li><li>开n次方</li><li>保留n位小数</li><li>是否约等于n</li></ul></li></ul><h4 id="随机数" tabindex="-1">随机数 <a class="header-anchor" href="#随机数" aria-label="Permalink to “随机数”">​</a></h4><ul><li>用于在一个区间内生成随机值。</li><li>结果可以是整数，也可以是小数。</li><li>当前可确认区间是包含端点的。</li></ul><h3 id="真假值篇" tabindex="-1">真假值篇 <a class="header-anchor" href="#真假值篇" aria-label="Permalink to “真假值篇”">​</a></h3><p>当前可稳定确认真假值专题至少包含：</p><ul><li>真假值类型</li><li>逻辑运算</li><li>真假判断</li><li>关系运算符</li><li>范围判断</li><li>存在判断</li><li>存在组件判断</li></ul><h4 id="真假值类型" tabindex="-1">真假值类型 <a class="header-anchor" href="#真假值类型" aria-label="Permalink to “真假值类型”">​</a></h4><ul><li>真假值只有两个值：<code>真</code> 与 <code>假</code>。</li><li>是所有条件判断与分支逻辑的基础。</li></ul><h4 id="逻辑运算" tabindex="-1">逻辑运算 <a class="header-anchor" href="#逻辑运算" aria-label="Permalink to “逻辑运算”">​</a></h4><ul><li>当前可确认包括： <ul><li>或（OR）</li><li>且（AND）</li></ul></li><li>多级嵌套时遵循 <code>先内后外</code>。</li></ul><h4 id="真假判断" tabindex="-1">真假判断 <a class="header-anchor" href="#真假判断" aria-label="Permalink to “真假判断”">​</a></h4><ul><li>用于判断一个真假值到底是真还是假。</li><li>判断结果本身仍是真假值，因此还能继续嵌套。</li></ul><h4 id="关系运算符" tabindex="-1">关系运算符 <a class="header-anchor" href="#关系运算符" aria-label="Permalink to “关系运算符”">​</a></h4><ul><li>当前可确认包括： <ul><li>等于</li><li>不等于</li><li>大于</li><li>小于</li><li>大于等于</li><li>小于等于</li></ul></li></ul><h4 id="范围判断" tabindex="-1">范围判断 <a class="header-anchor" href="#范围判断" aria-label="Permalink to “范围判断”">​</a></h4><ul><li>本质上是两个关系判断的组合，用于判断值是否落在指定区间内。</li></ul><h4 id="存在判断" tabindex="-1">存在判断 <a class="header-anchor" href="#存在判断" aria-label="Permalink to “存在判断”">​</a></h4><ul><li>用于判断某个对象、子物体或目标是否存在。</li></ul><h4 id="存在组件判断" tabindex="-1">存在组件判断 <a class="header-anchor" href="#存在组件判断" aria-label="Permalink to “存在组件判断”">​</a></h4><ul><li>用于判断某个具体物体身上是否挂载某个组件。</li></ul><h3 id="文字篇" tabindex="-1">文字篇 <a class="header-anchor" href="#文字篇" aria-label="Permalink to “文字篇”">​</a></h3><p>当前可稳定确认文本专题至少包含：</p><ul><li>文本类型</li><li>拼接文本</li><li>文本指令</li></ul><h4 id="文本类型" tabindex="-1">文本类型 <a class="header-anchor" href="#文本类型" aria-label="Permalink to “文本类型”">​</a></h4><ul><li>用于存储中文、英文、数字字符、符号等文字内容。</li></ul><h4 id="拼接文本" tabindex="-1">拼接文本 <a class="header-anchor" href="#拼接文本" aria-label="Permalink to “拼接文本”">​</a></h4><ul><li>用于把多个文本片段连接成一个新文本。</li><li>特别适合动态文案、欢迎语、变量播报。</li></ul><h4 id="文本指令" tabindex="-1">文本指令 <a class="header-anchor" href="#文本指令" aria-label="Permalink to “文本指令”">​</a></h4><p>当前可确认包含：</p><ul><li>长度</li><li>查找序号</li><li>替换全部</li><li>替换第一个子文本</li><li>在第n位插入</li><li>取第n个字</li><li>从第x到第y位的文字</li><li>以某字开头</li><li>以某字结尾</li><li>是否包含</li><li>转换成数字</li><li>分割成数组</li></ul><h3 id="数组篇" tabindex="-1">数组篇 <a class="header-anchor" href="#数组篇" aria-label="Permalink to “数组篇”">​</a></h3><p>当前可稳定确认数组专题至少包含：</p><ul><li>数组</li><li>数组的属性和指令</li></ul><h4 id="数组" tabindex="-1">数组 <a class="header-anchor" href="#数组" aria-label="Permalink to “数组”">​</a></h4><ul><li>数组是按顺序存储多个同类型数据的容器。</li><li>关键术语包括： <ul><li>元素</li><li>索引</li><li>长度</li></ul></li><li>当前可确认创游支持： <ul><li>一维数组</li><li>二维数组</li></ul></li><li>数组越界规则很关键： <ul><li>读取越界：返回空</li><li>写入越界：系统自动补全中间空位</li></ul></li></ul><h3 id="表篇" tabindex="-1">表篇 <a class="header-anchor" href="#表篇" aria-label="Permalink to “表篇”">​</a></h3><p>当前可稳定确认表专题至少包含：</p><ul><li>配置表</li><li>配置表的属性和指令</li></ul><h4 id="配置表" tabindex="-1">配置表 <a class="header-anchor" href="#配置表" aria-label="Permalink to “配置表”">​</a></h4><ul><li>配置表用于存储结构化静态数据。</li><li>需要与 <code>变量表</code>、<code>表结构</code> 区分理解。</li><li>运行时虽然能改，但通常不会永久改写原始配置内容。</li></ul><h3 id="对-ai-的可用标签-26" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-26" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>数字篇</li><li>真假值篇</li><li>文字篇</li><li>数组篇</li><li>表篇</li><li>NaN</li><li>三角函数</li><li>文本指令</li><li>数组越界</li><li>配置表</li></ul><hr><h2 id="_31-官方教程系统总览-对象、组件、脚本、ui、数据之间的关系" tabindex="-1">31. 官方教程系统总览：对象、组件、脚本、UI、数据之间的关系 <a class="header-anchor" href="#_31-官方教程系统总览-对象、组件、脚本、ui、数据之间的关系" aria-label="Permalink to “31. 官方教程系统总览：对象、组件、脚本、UI、数据之间的关系”">​</a></h2><h3 id="主题-27" tabindex="-1">主题 <a class="header-anchor" href="#主题-27" aria-label="Permalink to “主题”">​</a></h3><p>官方教程整体知识结构的统一理解</p><h3 id="一条主线理解" tabindex="-1">一条主线理解 <a class="header-anchor" href="#一条主线理解" aria-label="Permalink to “一条主线理解”">​</a></h3><p>从当前已整理的官方教程内容看，创游世界的知识体系大致可以理解为下面这条主线：</p><ul><li><code>素材</code> 是模板</li><li><code>物体</code> 是素材放入地图后的实例</li><li><code>组件</code> 决定物体具备什么能力</li><li><code>属性 / 指令 / 事件</code> 是组件内部的三类核心构成</li><li><code>脚本</code> 负责把这些能力按时序、条件和作用域组织起来</li><li><code>UI</code> 负责把交互暴露给玩家</li><li><code>表 / 变量 / 坐标向量</code> 负责承载数据与空间计算</li></ul><h3 id="对象层" tabindex="-1">对象层 <a class="header-anchor" href="#对象层" aria-label="Permalink to “对象层”">​</a></h3><ul><li><code>素材</code>：资源模板，决定对象属于什么类型。</li><li><code>物体</code>：素材进入地图后的实例，真正参与游戏运行。</li><li><code>地图</code>：承载物体、层级、摄像机、地图 UI 等内容的运行场景。</li><li><code>玩家</code>：既是控制主体，也是一个独立的数据与属性作用域。</li></ul><h3 id="能力层" tabindex="-1">能力层 <a class="header-anchor" href="#能力层" aria-label="Permalink to “能力层”">​</a></h3><ul><li><code>组件</code> 给素材/物体赋予能力。</li><li>一个组件通常包括： <ul><li>属性</li><li>指令</li><li>事件</li></ul></li><li>例如： <ul><li>生命组件负责生命值与受击死亡事件</li><li>武器槽组件负责武器装备与命中/击杀事件</li><li>物体UI组件负责绑定显示层</li></ul></li></ul><h3 id="逻辑层" tabindex="-1">逻辑层 <a class="header-anchor" href="#逻辑层" aria-label="Permalink to “逻辑层”">​</a></h3><ul><li><code>脚本</code> 用来组合多个组件能力，形成完整玩法。</li><li>脚本里重点依赖： <ul><li>局部变量</li><li>判断</li><li>循环</li><li>等待</li><li>渐变</li><li>执行指令</li><li>触发事件</li></ul></li><li>广播则承担“多对象之间解耦通知”的作用。</li></ul><h3 id="交互层" tabindex="-1">交互层 <a class="header-anchor" href="#交互层" aria-label="Permalink to “交互层”">​</a></h3><ul><li><code>UI</code> 把逻辑和玩家操作连接起来。</li><li>当前可确认至少有三层 UI： <ul><li>地图 UI</li><li>操作 UI</li><li>物体 UI</li></ul></li><li>输入类控件包括： <ul><li>按钮</li><li>输入框</li><li>摇杆</li><li>技能摇杆</li><li>移动摇杆</li><li>互动按钮</li><li>快捷聊天按钮</li></ul></li></ul><h3 id="数据层" tabindex="-1">数据层 <a class="header-anchor" href="#数据层" aria-label="Permalink to “数据层”">​</a></h3><ul><li><code>局部变量</code>：承载单次脚本过程中的中间数据。</li><li><code>玩家变量/变量表</code>：承载玩家运行状态与持久化数据。</li><li><code>配置表</code>：承载静态规则、策划参数和结构化配置。</li><li><code>数组 / 结构体 / 物品类型 / 真假值 / 文本 / 数字</code>：共同组成脚本数据系统。</li></ul><h3 id="空间层" tabindex="-1">空间层 <a class="header-anchor" href="#空间层" aria-label="Permalink to “空间层”">​</a></h3><ul><li><code>坐标</code> 负责位置。</li><li><code>向量</code> 负责方向和位移。</li><li><code>地图坐标</code> 与 <code>UI 坐标</code> 不是同一套空间，需要在某些玩法中做转换。</li><li>这也是卡牌拖拽放置等功能的核心难点之一。</li></ul><h3 id="对-ai-的可用标签-27" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-27" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>知识结构总览</li><li>素材与物体</li><li>组件系统</li><li>脚本系统</li><li>UI 系统</li><li>数据系统</li><li>坐标向量</li><li>官方教程总图</li></ul><hr><h2 id="_32-ui-系统专题总表" tabindex="-1">32. UI 系统专题总表 <a class="header-anchor" href="#_32-ui-系统专题总表" aria-label="Permalink to “32. UI 系统专题总表”">​</a></h2><h3 id="主题-28" tabindex="-1">主题 <a class="header-anchor" href="#主题-28" aria-label="Permalink to “主题”">​</a></h3><p>地图 UI、操作 UI、物体 UI 与输入组件的整体关系</p><h3 id="ui-分类总览" tabindex="-1">UI 分类总览 <a class="header-anchor" href="#ui-分类总览" aria-label="Permalink to “UI 分类总览”">​</a></h3><p>当前可确认创游 UI 体系至少分为三类：</p><ul><li><code>地图UI</code></li><li><code>操作UI</code></li><li><code>物体UI</code></li></ul><h3 id="地图ui" tabindex="-1">地图UI <a class="header-anchor" href="#地图ui" aria-label="Permalink to “地图UI”">​</a></h3><ul><li>属于地图级界面。</li><li>进入地图后即可存在，与角色本身无强绑定关系。</li><li>更适合放： <ul><li>地图级信息面板</li><li>关卡提示</li><li>公共 HUD</li><li>非角色专属交互界面</li></ul></li></ul><h3 id="操作ui" tabindex="-1">操作UI <a class="header-anchor" href="#操作ui" aria-label="Permalink to “操作UI”">​</a></h3><ul><li>与角色绑定。</li><li>适合角色操作、战斗控制、技能释放、交互按钮等。</li><li>当前可确认操作 UI 中涵盖的素材类型很多，包括： <ul><li>按钮</li><li>勾选按钮</li><li>摇杆</li><li>技能摇杆</li><li>移动摇杆</li><li>武器道具摇杆</li><li>输入框</li><li>滑动条</li><li>进度条</li><li>跳跃按钮</li><li>互动按钮</li><li>货币条</li></ul></li><li>操作 UI 具备明确生命周期： <ul><li>当UI开始时</li><li>当收到广播时</li><li>当UI销毁时</li></ul></li></ul><h3 id="物体ui" tabindex="-1">物体UI <a class="header-anchor" href="#物体ui" aria-label="Permalink to “物体UI”">​</a></h3><ul><li>绑定在某个具体物体上。</li><li>当前可确认只有： <ul><li>角色</li><li>装置 可以挂载物体UI组件。</li></ul></li><li>典型适合做： <ul><li>血条</li><li>头顶提示</li><li>状态标识</li></ul></li><li>一个关键特性是： <ul><li>它不会随着物体翻转而翻转。</li></ul></li></ul><h3 id="常见问题映射" tabindex="-1">常见问题映射 <a class="header-anchor" href="#常见问题映射" aria-label="Permalink to “常见问题映射”">​</a></h3><ul><li>找不到做好的 UI：多半是找错 UI 类型对应的切换入口。</li><li>UI 重叠关不掉：常与 <code>默认操作UI</code> 仍在生效有关。</li><li>互动按钮不显示：默认只有碰到 <code>可互动物体</code> 时才会显示。</li></ul><h3 id="输入控件分工" tabindex="-1">输入控件分工 <a class="header-anchor" href="#输入控件分工" aria-label="Permalink to “输入控件分工”">​</a></h3><ul><li><code>移动摇杆</code>：更偏角色移动专用。</li><li><code>摇杆</code>：更偏自定义方向输入。</li><li><code>技能摇杆</code>：更偏技能位输入与方向采集。</li><li><code>输入框</code>：更偏文本输入。</li><li><code>互动按钮</code>：更偏上下文交互。</li><li><code>快捷聊天按钮</code>：更偏聊天入口。</li></ul><h3 id="对-ai-的可用标签-28" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-28" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>地图UI</li><li>操作UI</li><li>物体UI</li><li>默认操作UI</li><li>UI切换</li><li>输入控件</li><li>互动按钮</li><li>输入框</li><li>摇杆</li><li>UI总表</li></ul><hr><h2 id="_33-战斗系统专题总表" tabindex="-1">33. 战斗系统专题总表 <a class="header-anchor" href="#_33-战斗系统专题总表" aria-label="Permalink to “33. 战斗系统专题总表”">​</a></h2><h3 id="主题-29" tabindex="-1">主题 <a class="header-anchor" href="#主题-29" aria-label="Permalink to “主题”">​</a></h3><p>生命、近战武器、子弹、武器槽、角色、弹簧等战斗与交互能力的关系</p><h3 id="角色作为战斗主体" tabindex="-1">角色作为战斗主体 <a class="header-anchor" href="#角色作为战斗主体" aria-label="Permalink to “角色作为战斗主体”">​</a></h3><ul><li><code>角色组件</code> 决定对象是否能作为主角/角色主体。</li><li>角色组件依赖物理组件。</li><li>它负责： <ul><li>移动方式</li><li>朝向</li><li>动画</li><li>跳跃能力</li><li>行动参数</li></ul></li></ul><h3 id="生命系统" tabindex="-1">生命系统 <a class="header-anchor" href="#生命系统" aria-label="Permalink to “生命系统”">​</a></h3><ul><li><code>生命组件</code> 决定对象是否可以承受伤害。</li><li>当前可确认核心内容包括： <ul><li>血量</li><li>被击退比例</li><li>受击后无敌</li><li>血条显示时机</li><li>受击显示飘字</li><li>当受击时</li><li>当死亡时</li></ul></li><li>死亡并不一定自动销毁对象，很多时候要在脚本里自行处理善后。</li></ul><h3 id="近战系统" tabindex="-1">近战系统 <a class="header-anchor" href="#近战系统" aria-label="Permalink to “近战系统”">​</a></h3><ul><li><code>近战武器组件</code> 可以直接造成伤害。</li><li>当前可确认它不仅有基础伤害值，还有更完整战斗参数： <ul><li>伤害类型</li><li>暴击率</li><li>暴击倍数</li><li>击退距离</li><li>击退速度</li><li>攻击频率</li><li>特殊效果</li><li>当攻击时</li><li>当打到目标时</li><li>当杀死目标时</li></ul></li><li>判定上更依赖碰撞盒覆盖范围，而不是纯贴图是否碰上。</li></ul><h3 id="远程系统" tabindex="-1">远程系统 <a class="header-anchor" href="#远程系统" aria-label="Permalink to “远程系统”">​</a></h3><ul><li><code>子弹组件</code> 是远程系统的重要核心。</li><li>远程武器本体往往不直接承担伤害，真正造成伤害的通常是子弹。</li><li>子弹当前可确认的能力包括： <ul><li>重力倍数</li><li>推进加速度</li><li>子弹特效</li><li>反弹次数</li><li>穿透个数</li></ul></li></ul><h3 id="装备系统" tabindex="-1">装备系统 <a class="header-anchor" href="#装备系统" aria-label="Permalink to “装备系统”">​</a></h3><ul><li><code>武器槽组件</code> 负责把武器挂到角色或装置上。</li><li>并且还负责： <ul><li>自动瞄准</li><li>锁敌半径</li><li>命中回调</li><li>击杀回调</li><li>武器改变事件</li></ul></li></ul><h3 id="特效与场景交互" tabindex="-1">特效与场景交互 <a class="header-anchor" href="#特效与场景交互" aria-label="Permalink to “特效与场景交互”">​</a></h3><ul><li><code>粒子特效组件</code> 已确认存在，但属性仍待补充。</li><li><code>弹簧组件</code> 属于强交互装置，可把角色弹飞，并触发 <code>当弹起时</code> 事件。</li></ul><h3 id="战斗系统的一条简化关系链" tabindex="-1">战斗系统的一条简化关系链 <a class="header-anchor" href="#战斗系统的一条简化关系链" aria-label="Permalink to “战斗系统的一条简化关系链”">​</a></h3><ul><li>角色拥有武器槽</li><li>武器槽装备近战或远程武器</li><li>近战可直接造成伤害 / 远程通常通过子弹造成伤害</li><li>目标通过生命组件接收伤害</li><li>命中、击杀、死亡再通过事件回调串联后续逻辑</li></ul><h3 id="对-ai-的可用标签-29" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-29" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>战斗系统</li><li>角色组件</li><li>生命组件</li><li>近战武器</li><li>子弹组件</li><li>武器槽组件</li><li>暴击</li><li>击退</li><li>自动瞄准</li><li>战斗关系链</li></ul><hr><h2 id="_34-数据与脚本系统专题总表" tabindex="-1">34. 数据与脚本系统专题总表 <a class="header-anchor" href="#_34-数据与脚本系统专题总表" aria-label="Permalink to “34. 数据与脚本系统专题总表”">​</a></h2><h3 id="主题-30" tabindex="-1">主题 <a class="header-anchor" href="#主题-30" aria-label="Permalink to “主题”">​</a></h3><p>变量、表、数组、结构体、真假值、文本、数字与控制流的总入口</p><h3 id="数据类型层" tabindex="-1">数据类型层 <a class="header-anchor" href="#数据类型层" aria-label="Permalink to “数据类型层”">​</a></h3><p>当前已确认的重要数据主题包括：</p><ul><li>数字</li><li>真假值</li><li>文本</li><li>数组</li><li>配置表</li><li>结构体</li><li>物品类型</li><li>坐标与向量</li></ul><h3 id="变量层" tabindex="-1">变量层 <a class="header-anchor" href="#变量层" aria-label="Permalink to “变量层”">​</a></h3><ul><li><code>局部变量</code>：脚本过程中的临时数据容器。</li><li><code>玩家变量</code>：跨会话、可云存储、适合记录个人状态。</li><li><code>属性设置语句</code>：从主体角度修改自身/系统/地图/玩家层的数据。</li></ul><h3 id="表层" tabindex="-1">表层 <a class="header-anchor" href="#表层" aria-label="Permalink to “表层”">​</a></h3><ul><li><code>配置表</code>：静态规则与策划数据。</li><li><code>变量表/玩家变量表</code>：更偏动态状态。</li><li>重要经验： <ul><li>静态规则尽量放配置表</li><li>老用户数据同步问题往往发生在变量表变更后</li></ul></li></ul><h3 id="结构层" tabindex="-1">结构层 <a class="header-anchor" href="#结构层" aria-label="Permalink to “结构层”">​</a></h3><ul><li><code>数组</code> 适合承载同类型顺序数据。</li><li><code>结构体</code> 适合把多个不同字段组合为一个整体对象。</li><li><code>物品类型</code> 说明脚本系统里还存在更偏游戏对象化的数据类型。</li></ul><h3 id="基础运算层" tabindex="-1">基础运算层 <a class="header-anchor" href="#基础运算层" aria-label="Permalink to “基础运算层”">​</a></h3><ul><li>数字系统提供： <ul><li>四则运算</li><li>取余</li><li>三角函数</li><li>常见数值处理指令</li><li>随机数</li></ul></li><li>真假值系统提供： <ul><li>逻辑运算</li><li>真假判断</li><li>关系运算</li><li>范围判断</li><li>存在判断</li><li>存在组件判断</li></ul></li><li>文本系统提供： <ul><li>拼接</li><li>搜索</li><li>替换</li><li>截取</li><li>判断</li><li>转换成数字</li><li>分割成数组</li></ul></li></ul><h3 id="控制流层" tabindex="-1">控制流层 <a class="header-anchor" href="#控制流层" aria-label="Permalink to “控制流层”">​</a></h3><ul><li>判断语句</li><li>循环语句</li><li>等待语句</li><li>概率执行</li><li>退出脚本</li><li>渐变语句</li><li>执行指令</li><li>触发事件</li></ul><h3 id="一条总理解" tabindex="-1">一条总理解 <a class="header-anchor" href="#一条总理解" aria-label="Permalink to “一条总理解”">​</a></h3><p>从当前官方教程来看，创游脚本体系已经具备：</p><ul><li>数据表达能力</li><li>数据运算能力</li><li>条件分支能力</li><li>循环处理能力</li><li>事件驱动能力</li><li>多作用域调用能力</li></ul><h3 id="对-ai-的可用标签-30" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-30" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>脚本系统</li><li>数据系统</li><li>局部变量</li><li>配置表</li><li>玩家变量表</li><li>数组</li><li>结构体</li><li>真假值</li><li>文本指令</li><li>控制流</li></ul><hr><h2 id="_35-常见问题与实用功能专题导航" tabindex="-1">35. 常见问题与实用功能专题导航 <a class="header-anchor" href="#_35-常见问题与实用功能专题导航" aria-label="Permalink to “35. 常见问题与实用功能专题导航”">​</a></h2><h3 id="主题-31" tabindex="-1">主题 <a class="header-anchor" href="#主题-31" aria-label="Permalink to “主题”">​</a></h3><p>把“问题排查”和“功能实现”作为两个独立入口理解</p><h3 id="常见问题更偏-排错入口" tabindex="-1">常见问题更偏“排错入口” <a class="header-anchor" href="#常见问题更偏-排错入口" aria-label="Permalink to “常见问题更偏“排错入口””">​</a></h3><p>当前已确认的高频问题包括：</p><ul><li>如何添加玩家</li><li>为什么表改了之后不生效</li><li>为什么切换 UI 时找不到做好的 UI</li><li>为什么有两个重叠的 UI 还关不掉</li><li>为什么角色在地图上走不动</li><li>为什么 UI-互动按钮不在屏幕中显示</li><li>为什么修改了素材属性，地图中无变化</li><li>碰撞盒与阻挡通行</li></ul><h3 id="这些问题背后的核心知识点" tabindex="-1">这些问题背后的核心知识点 <a class="header-anchor" href="#这些问题背后的核心知识点" aria-label="Permalink to “这些问题背后的核心知识点”">​</a></h3><ul><li>数据同步问题 -&gt; 玩家变量表与配置表边界</li><li>UI 问题 -&gt; 地图UI / 操作UI / 物体UI 分类</li><li>移动问题 -&gt; 碰撞盒与阻挡通行</li><li>素材不生效 -&gt; 模板与实例化关系</li><li>玩家丢失 -&gt; 编辑器角色添加入口</li></ul><h3 id="实用功能更偏-方案入口" tabindex="-1">实用功能更偏“方案入口” <a class="header-anchor" href="#实用功能更偏-方案入口" aria-label="Permalink to “实用功能更偏“方案入口””">​</a></h3><p>当前已确认的功能实现主题包括：</p><ul><li>卡牌拖拽放置</li><li>计算玩家未登录天数</li><li>怎么做玩家首次登录</li></ul><h3 id="这些功能背后的基础能力" tabindex="-1">这些功能背后的基础能力 <a class="header-anchor" href="#这些功能背后的基础能力" aria-label="Permalink to “这些功能背后的基础能力”">​</a></h3><ul><li>卡牌拖拽放置 -&gt; UI 坐标与地图坐标转换</li><li>未登录天数 -&gt; 时间戳、玩家变量、云存储</li><li>首次登录 -&gt; 真假值玩家变量 + 一次性逻辑控制</li></ul><h3 id="建议的后续拆分方向" tabindex="-1">建议的后续拆分方向 <a class="header-anchor" href="#建议的后续拆分方向" aria-label="Permalink to “建议的后续拆分方向”">​</a></h3><p>后续可继续把“常见问题”和“实用功能”分别拆成两个专题总表：</p><ul><li><code>常见问题总索引</code></li><li><code>功能实现总索引</code> 并为每一条问题或功能补：</li><li>现象</li><li>原因</li><li>解决思路</li><li>关联基础知识</li><li>对应 OCR 证据页</li></ul><h3 id="对-ai-的可用标签-31" tabindex="-1">对 AI 的可用标签 <a class="header-anchor" href="#对-ai-的可用标签-31" aria-label="Permalink to “对 AI 的可用标签”">​</a></h3><ul><li>常见问题</li><li>实用功能</li><li>问题排查</li><li>功能实现</li><li>坐标转换</li><li>时间戳</li><li>首次登录</li><li>UI 问题</li><li>数据同步</li></ul><hr>',574)])])}const f=i(h,[["render",d]]);export{b as __pageData,f as default};
